window.SCERE_STOCKS_SVGS = {
  "stocks-01-1-residual-claim": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 560\" font-family=\"Arial, Helvetica, sans-serif\" role=\"img\">\n  <rect x=\"0\" y=\"0\" width=\"900\" height=\"560\" fill=\"#0f172a\"/>\n  <text x=\"450\" y=\"34\" text-anchor=\"middle\" font-size=\"21\" fill=\"#e2e8f0\" font-weight=\"bold\">The Residual Claim: Who Gets Paid, in What Order</text>\n  <text x=\"450\" y=\"57\" text-anchor=\"middle\" font-size=\"13\" fill=\"#94a3b8\">The same company, two years. Everyone above the shareholder is paid a fixed amount first.</text>\n  <text x=\"215\" y=\"92\" text-anchor=\"middle\" font-size=\"15\" fill=\"#4ade80\" font-weight=\"bold\">A good year: revenue 100</text>\n  <rect x=\"150\" y=\"334\" width=\"130\" height=\"136\" fill=\"#94a3b8\"/>\n  <text x=\"215\" y=\"407\" text-anchor=\"middle\" font-size=\"12\" fill=\"#0f172a\" font-weight=\"bold\">40</text>\n  <text x=\"292\" y=\"407\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">Suppliers</text>\n  <rect x=\"150\" y=\"215\" width=\"130\" height=\"119\" fill=\"#3b82f6\"/>\n  <text x=\"215\" y=\"279.5\" text-anchor=\"middle\" font-size=\"12\" fill=\"#0f172a\" font-weight=\"bold\">35</text>\n  <text x=\"292\" y=\"279.5\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">Staff</text>\n  <rect x=\"150\" y=\"181\" width=\"130\" height=\"34\" fill=\"#eab308\"/>\n  <text x=\"215\" y=\"203\" text-anchor=\"middle\" font-size=\"12\" fill=\"#0f172a\" font-weight=\"bold\">10</text>\n  <text x=\"292\" y=\"203\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">Interest on debt</text>\n  <rect x=\"150\" y=\"164\" width=\"130\" height=\"17\" fill=\"#ef4444\"/>\n  <text x=\"215\" y=\"177.5\" text-anchor=\"middle\" font-size=\"12\" fill=\"#0f172a\" font-weight=\"bold\">5</text>\n  <text x=\"292\" y=\"177.5\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">Tax</text>\n  <rect x=\"150\" y=\"130\" width=\"130\" height=\"34\" fill=\"#22c55e\"/>\n  <text x=\"215\" y=\"152\" text-anchor=\"middle\" font-size=\"12\" fill=\"#0f172a\" font-weight=\"bold\">10</text>\n  <text x=\"292\" y=\"152\" text-anchor=\"start\" font-size=\"12\" fill=\"#4ade80\">Residual: yours</text>\n  <text x=\"660\" y=\"92\" text-anchor=\"middle\" font-size=\"15\" fill=\"#f87171\" font-weight=\"bold\">Revenue falls 10, to 90</text>\n  <rect x=\"595\" y=\"334\" width=\"130\" height=\"136\" fill=\"#94a3b8\"/>\n  <text x=\"660\" y=\"407\" text-anchor=\"middle\" font-size=\"12\" fill=\"#0f172a\" font-weight=\"bold\">40</text>\n  <text x=\"737\" y=\"407\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">Suppliers</text>\n  <rect x=\"595\" y=\"215\" width=\"130\" height=\"119\" fill=\"#3b82f6\"/>\n  <text x=\"660\" y=\"279.5\" text-anchor=\"middle\" font-size=\"12\" fill=\"#0f172a\" font-weight=\"bold\">35</text>\n  <text x=\"737\" y=\"279.5\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">Staff</text>\n  <rect x=\"595\" y=\"181\" width=\"130\" height=\"34\" fill=\"#eab308\"/>\n  <text x=\"660\" y=\"203\" text-anchor=\"middle\" font-size=\"12\" fill=\"#0f172a\" font-weight=\"bold\">10</text>\n  <text x=\"737\" y=\"203\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">Interest on debt</text>\n  <rect x=\"595\" y=\"164\" width=\"130\" height=\"17\" fill=\"#ef4444\"/>\n  <text x=\"660\" y=\"177.5\" text-anchor=\"middle\" font-size=\"12\" fill=\"#0f172a\" font-weight=\"bold\">5</text>\n  <text x=\"737\" y=\"177.5\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">Tax</text>\n  <rect x=\"595\" y=\"164\" width=\"130\" height=\"0\" fill=\"#22c55e\"/>\n  <text x=\"737\" y=\"158\" text-anchor=\"start\" font-size=\"12\" fill=\"#f87171\">Residual: nothing</text>\n  <line x1=\"60\" y1=\"470\" x2=\"840\" y2=\"470\" stroke=\"#334155\" stroke-width=\"2\"/>\n  <text x=\"450\" y=\"508\" text-anchor=\"middle\" font-size=\"15\" fill=\"#facc15\" font-weight=\"bold\">Revenue fell 10%. The shareholders' claim fell 100%.</text>\n  <text x=\"450\" y=\"532\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">This is why share prices move so much more than the businesses underneath them.</text>\n</svg>",
  "stocks-01-2-positive-vs-zero-sum": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 560\" font-family=\"Arial, Helvetica, sans-serif\" role=\"img\">\n  <rect x=\"0\" y=\"0\" width=\"900\" height=\"560\" fill=\"#0f172a\"/>\n  <text x=\"450\" y=\"34\" text-anchor=\"middle\" font-size=\"21\" fill=\"#e2e8f0\" font-weight=\"bold\">Where Does the Money Come From?</text>\n  <text x=\"450\" y=\"57\" text-anchor=\"middle\" font-size=\"13\" fill=\"#94a3b8\">The distinction is not how risky it feels. It is whether anything is being created.</text>\n  <rect x=\"30\" y=\"84\" width=\"409\" height=\"430\" rx=\"10\" fill=\"#0f172a\" stroke=\"#ef4444\" stroke-width=\"2\"/>\n  <text x=\"234.5\" y=\"114\" text-anchor=\"middle\" font-size=\"16\" fill=\"#f87171\" font-weight=\"bold\">Roulette: zero-sum, minus the house</text>\n  <text x=\"46\" y=\"146\" text-anchor=\"start\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">The wheel produces nothing.</text>\n  <text x=\"46\" y=\"173\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">Every unit won by one player is a unit lost by another.</text>\n  <text x=\"46\" y=\"210\" text-anchor=\"start\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">37 pockets, a single number pays 35 to 1.</text>\n  <text x=\"46\" y=\"237\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">Expected value per unit staked: about 0.973 units</text>\n  <text x=\"46\" y=\"256\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">returned.</text>\n  <text x=\"46\" y=\"293\" text-anchor=\"start\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">A loss of about 2.7% per spin, on average, forever.</text>\n  <text x=\"46\" y=\"320\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">This is a property of the wheel. No amount of skill</text>\n  <text x=\"46\" y=\"339\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">changes it.</text>\n  <rect x=\"461\" y=\"84\" width=\"409\" height=\"430\" rx=\"10\" fill=\"#0f172a\" stroke=\"#22c55e\" stroke-width=\"2\"/>\n  <text x=\"665.5\" y=\"114\" text-anchor=\"middle\" font-size=\"16\" fill=\"#4ade80\" font-weight=\"bold\">Owning businesses: positive-sum</text>\n  <text x=\"477\" y=\"146\" text-anchor=\"start\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">The companies employ people and sell things.</text>\n  <text x=\"477\" y=\"173\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">Cash is generated outside the transactions between</text>\n  <text x=\"477\" y=\"192\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">investors.</text>\n  <text x=\"477\" y=\"229\" text-anchor=\"start\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">That cash reaches the residual claim (Lesson 1).</text>\n  <text x=\"477\" y=\"256\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">Every owner can gain at once, because value was created.</text>\n  <text x=\"477\" y=\"293\" text-anchor=\"start\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">But only over holding periods long enough for it to</text>\n  <text x=\"477\" y=\"312\" text-anchor=\"start\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">matter.</text>\n  <text x=\"477\" y=\"339\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">Over minutes, the businesses have produced nothing new,</text>\n  <text x=\"477\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">and trading is the roulette column again.</text>\n</svg>",
  "stocks-01-3-order-book": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 560\" font-family=\"Arial, Helvetica, sans-serif\" role=\"img\">\n  <rect x=\"0\" y=\"0\" width=\"900\" height=\"560\" fill=\"#0f172a\"/>\n  <text x=\"450\" y=\"34\" text-anchor=\"middle\" font-size=\"21\" fill=\"#e2e8f0\" font-weight=\"bold\">There Is No Single Price</text>\n  <text x=\"450\" y=\"57\" text-anchor=\"middle\" font-size=\"13\" fill=\"#94a3b8\">A share quoted at 25.00. The quote is the midpoint, and nobody is offering it.</text>\n  <rect x=\"250\" y=\"92\" width=\"400\" height=\"150\" rx=\"8\" fill=\"#0f172a\" stroke=\"#ef4444\" stroke-width=\"2\"/>\n  <text x=\"450\" y=\"116\" text-anchor=\"middle\" font-size=\"14\" fill=\"#f87171\" font-weight=\"bold\">Sellers: the ask side</text>\n  <text x=\"300\" y=\"148\" text-anchor=\"start\" font-size=\"14\" fill=\"#e2e8f0\">25.06</text>\n  <text x=\"560\" y=\"148\" text-anchor=\"end\" font-size=\"13\" fill=\"#94a3b8\">400 shares</text>\n  <text x=\"300\" y=\"176\" text-anchor=\"start\" font-size=\"14\" fill=\"#e2e8f0\">25.04</text>\n  <text x=\"560\" y=\"176\" text-anchor=\"end\" font-size=\"13\" fill=\"#94a3b8\">900 shares</text>\n  <text x=\"300\" y=\"210\" text-anchor=\"start\" font-size=\"17\" fill=\"#f87171\" font-weight=\"bold\">25.02</text>\n  <text x=\"560\" y=\"210\" text-anchor=\"end\" font-size=\"13\" fill=\"#f87171\">1,200 shares — best ask</text>\n  <line x1=\"250\" y1=\"258\" x2=\"650\" y2=\"258\" stroke=\"#eab308\" stroke-width=\"2\" stroke-dasharray=\"6 5\"/>\n  <text x=\"450\" y=\"280\" text-anchor=\"middle\" font-size=\"14\" fill=\"#facc15\" font-weight=\"bold\">Spread: 0.04. Quoted price 25.00 is the midpoint.</text>\n  <rect x=\"250\" y=\"296\" width=\"400\" height=\"150\" rx=\"8\" fill=\"#0f172a\" stroke=\"#22c55e\" stroke-width=\"2\"/>\n  <text x=\"300\" y=\"330\" text-anchor=\"start\" font-size=\"17\" fill=\"#4ade80\" font-weight=\"bold\">24.98</text>\n  <text x=\"560\" y=\"330\" text-anchor=\"end\" font-size=\"13\" fill=\"#4ade80\">1,100 shares — best bid</text>\n  <text x=\"300\" y=\"364\" text-anchor=\"start\" font-size=\"14\" fill=\"#e2e8f0\">24.96</text>\n  <text x=\"560\" y=\"364\" text-anchor=\"end\" font-size=\"13\" fill=\"#94a3b8\">700 shares</text>\n  <text x=\"300\" y=\"392\" text-anchor=\"start\" font-size=\"14\" fill=\"#e2e8f0\">24.94</text>\n  <text x=\"560\" y=\"392\" text-anchor=\"end\" font-size=\"13\" fill=\"#94a3b8\">1,500 shares</text>\n  <text x=\"450\" y=\"428\" text-anchor=\"middle\" font-size=\"14\" fill=\"#4ade80\" font-weight=\"bold\">Buyers: the bid side</text>\n  <text x=\"450\" y=\"486\" text-anchor=\"middle\" font-size=\"14\" fill=\"#e2e8f0\" font-weight=\"bold\">Buy at 25.02 and sell at 24.98 a moment later: down 0.16% with nothing having happened.</text>\n  <text x=\"450\" y=\"512\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">A market order crosses the spread on purpose. A limit order waits in the book instead.</text>\n</svg>",
  "stocks-01-4-index-weighting": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 560\" font-family=\"Arial, Helvetica, sans-serif\" role=\"img\">\n  <rect x=\"0\" y=\"0\" width=\"900\" height=\"560\" fill=\"#0f172a\"/>\n  <text x=\"450\" y=\"34\" text-anchor=\"middle\" font-size=\"21\" fill=\"#e2e8f0\" font-weight=\"bold\">Same Three Companies, Three Different Answers</text>\n  <text x=\"450\" y=\"57\" text-anchor=\"middle\" font-size=\"13\" fill=\"#94a3b8\">Company A: 300 a share, worth 10bn. Company B: 50 a share, worth 80bn. Company C: 100 a share, worth 30bn.</text>\n  <text x=\"318\" y=\"114\" text-anchor=\"end\" font-size=\"13\" fill=\"#e2e8f0\">A: influence when weighted by price</text>\n  <rect x=\"330\" y=\"96\" width=\"361.90476190476187\" height=\"26\" rx=\"3\" fill=\"#ef4444\"/>\n  <text x=\"701.9047619047619\" y=\"114\" text-anchor=\"start\" font-size=\"13\" fill=\"#f87171\" font-weight=\"bold\">67%</text>\n  <text x=\"318\" y=\"152\" text-anchor=\"end\" font-size=\"13\" fill=\"#e2e8f0\">B: influence when weighted by price</text>\n  <rect x=\"330\" y=\"134\" width=\"60.317460317460316\" height=\"26\" rx=\"3\" fill=\"#ef4444\"/>\n  <text x=\"400.3174603174603\" y=\"152\" text-anchor=\"start\" font-size=\"13\" fill=\"#f87171\" font-weight=\"bold\">11%</text>\n  <text x=\"318\" y=\"190\" text-anchor=\"end\" font-size=\"13\" fill=\"#e2e8f0\">C: influence when weighted by price</text>\n  <rect x=\"330\" y=\"172\" width=\"120.63492063492063\" height=\"26\" rx=\"3\" fill=\"#ef4444\"/>\n  <text x=\"460.6349206349206\" y=\"190\" text-anchor=\"start\" font-size=\"13\" fill=\"#f87171\" font-weight=\"bold\">22%</text>\n  <line x1=\"60\" y1=\"232\" x2=\"840\" y2=\"232\" stroke=\"#334155\" stroke-width=\"1\"/>\n  <text x=\"318\" y=\"268\" text-anchor=\"end\" font-size=\"13\" fill=\"#e2e8f0\">A: influence when weighted by market value</text>\n  <rect x=\"330\" y=\"250\" width=\"45.238095238095234\" height=\"26\" rx=\"3\" fill=\"#3b82f6\"/>\n  <text x=\"385.23809523809524\" y=\"268\" text-anchor=\"start\" font-size=\"13\" fill=\"#60a5fa\" font-weight=\"bold\">8%</text>\n  <text x=\"318\" y=\"306\" text-anchor=\"end\" font-size=\"13\" fill=\"#e2e8f0\">B: influence when weighted by market value</text>\n  <rect x=\"330\" y=\"288\" width=\"361.90476190476187\" height=\"26\" rx=\"3\" fill=\"#3b82f6\"/>\n  <text x=\"701.9047619047619\" y=\"306\" text-anchor=\"start\" font-size=\"13\" fill=\"#60a5fa\" font-weight=\"bold\">67%</text>\n  <text x=\"318\" y=\"344\" text-anchor=\"end\" font-size=\"13\" fill=\"#e2e8f0\">C: influence when weighted by market value</text>\n  <rect x=\"330\" y=\"326\" width=\"135.71428571428572\" height=\"26\" rx=\"3\" fill=\"#3b82f6\"/>\n  <text x=\"475.7142857142857\" y=\"344\" text-anchor=\"start\" font-size=\"13\" fill=\"#60a5fa\" font-weight=\"bold\">25%</text>\n  <line x1=\"60\" y1=\"386\" x2=\"840\" y2=\"386\" stroke=\"#334155\" stroke-width=\"1\"/>\n  <text x=\"318\" y=\"422\" text-anchor=\"end\" font-size=\"13\" fill=\"#e2e8f0\">A, B and C: equal weighting</text>\n  <rect x=\"330\" y=\"404\" width=\"180.77142857142857\" height=\"26\" rx=\"3\" fill=\"#22c55e\"/>\n  <text x=\"520.7714285714286\" y=\"422\" text-anchor=\"start\" font-size=\"13\" fill=\"#4ade80\" font-weight=\"bold\">33% each</text>\n  <text x=\"450\" y=\"486\" text-anchor=\"middle\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">The smallest company dominates a price-weighted index. The largest dominates a cap-weighted one.</text>\n  <text x=\"450\" y=\"510\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">Share price alone says nothing about the size of a company. \"The market rose 1%\" is a claim about a chosen rule.</text>\n</svg>",
  "stocks-01-5-etf-creation": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 560\" font-family=\"Arial, Helvetica, sans-serif\" role=\"img\">\n  <rect x=\"0\" y=\"0\" width=\"900\" height=\"560\" fill=\"#0f172a\"/>\n  <text x=\"450\" y=\"34\" text-anchor=\"middle\" font-size=\"21\" fill=\"#e2e8f0\" font-weight=\"bold\">Creation and Redemption: Why an ETF Price Tracks What It Holds</text>\n  <text x=\"450\" y=\"57\" text-anchor=\"middle\" font-size=\"13\" fill=\"#94a3b8\">An ETF trading at 100.40 while the basket it holds is worth 100.00.</text>\n  <rect x=\"40\" y=\"130\" width=\"170.5\" height=\"96\" rx=\"8\" fill=\"#0f172a\" stroke=\"#ef4444\" stroke-width=\"2\"/>\n  <text x=\"125.25\" y=\"158\" text-anchor=\"middle\" font-size=\"13\" fill=\"#ef4444\" font-weight=\"bold\">ETF trades above the</text>\n  <text x=\"125.25\" y=\"174\" text-anchor=\"middle\" font-size=\"13\" fill=\"#ef4444\" font-weight=\"bold\">basket</text>\n  <text x=\"125.25\" y=\"248\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">Price 100.40, net asset</text>\n  <text x=\"125.25\" y=\"263\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">value 100.00</text>\n  <text x=\"233.5\" y=\"183\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">then</text>\n  <rect x=\"256.5\" y=\"130\" width=\"170.5\" height=\"96\" rx=\"8\" fill=\"#0f172a\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n  <text x=\"341.75\" y=\"158\" text-anchor=\"middle\" font-size=\"13\" fill=\"#3b82f6\" font-weight=\"bold\">Authorised participant</text>\n  <text x=\"341.75\" y=\"174\" text-anchor=\"middle\" font-size=\"13\" fill=\"#3b82f6\" font-weight=\"bold\">buys the underlying</text>\n  <text x=\"341.75\" y=\"190\" text-anchor=\"middle\" font-size=\"13\" fill=\"#3b82f6\" font-weight=\"bold\">shares</text>\n  <text x=\"341.75\" y=\"248\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">Cost: 100.00 a share</text>\n  <text x=\"450\" y=\"183\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">then</text>\n  <rect x=\"473\" y=\"130\" width=\"170.5\" height=\"96\" rx=\"8\" fill=\"#0f172a\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n  <text x=\"558.25\" y=\"158\" text-anchor=\"middle\" font-size=\"13\" fill=\"#3b82f6\" font-weight=\"bold\">Delivers the basket,</text>\n  <text x=\"558.25\" y=\"174\" text-anchor=\"middle\" font-size=\"13\" fill=\"#3b82f6\" font-weight=\"bold\">receives new ETF shares</text>\n  <text x=\"558.25\" y=\"248\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">Creation, done with the fund</text>\n  <text x=\"666.5\" y=\"183\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">then</text>\n  <rect x=\"689.5\" y=\"130\" width=\"170.5\" height=\"96\" rx=\"8\" fill=\"#0f172a\" stroke=\"#22c55e\" stroke-width=\"2\"/>\n  <text x=\"774.75\" y=\"158\" text-anchor=\"middle\" font-size=\"13\" fill=\"#22c55e\" font-weight=\"bold\">Sells them on the</text>\n  <text x=\"774.75\" y=\"174\" text-anchor=\"middle\" font-size=\"13\" fill=\"#22c55e\" font-weight=\"bold\">exchange at 100.40</text>\n  <text x=\"774.75\" y=\"248\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">The extra supply pushes the</text>\n  <text x=\"774.75\" y=\"263\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">price down</text>\n  <line x1=\"60\" y1=\"330\" x2=\"840\" y2=\"330\" stroke=\"#334155\" stroke-width=\"1\"/>\n  <text x=\"450\" y=\"366\" text-anchor=\"middle\" font-size=\"15\" fill=\"#facc15\" font-weight=\"bold\">Pursuing the profit is what closes the gap. Nothing enforces it — an incentive does.</text>\n  <rect x=\"120\" y=\"392\" width=\"660\" height=\"118\" rx=\"8\" fill=\"#0f172a\" stroke=\"#eab308\" stroke-width=\"2\"/>\n  <text x=\"450\" y=\"420\" text-anchor=\"middle\" font-size=\"13\" fill=\"#facc15\" font-weight=\"bold\">Which is why premiums and discounts widen exactly when you least want them to</text>\n  <text x=\"450\" y=\"446\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">If the underlying market is closed, illiquid or falling fast, the participant cannot price or trade</text>\n  <text x=\"450\" y=\"466\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">the basket confidently. The mechanism weakens in exactly the conditions that make you want to sell.</text>\n  <text x=\"450\" y=\"494\" text-anchor=\"middle\" font-size=\"12\" fill=\"#e2e8f0\" font-weight=\"bold\">The SEC describes the market price as generally kept close to net asset value. Generally.</text>\n</svg>",
  "stocks-01-6-ex-dividend": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 560\" font-family=\"Arial, Helvetica, sans-serif\" role=\"img\">\n  <rect x=\"0\" y=\"0\" width=\"900\" height=\"560\" fill=\"#0f172a\"/>\n  <text x=\"450\" y=\"34\" text-anchor=\"middle\" font-size=\"21\" fill=\"#e2e8f0\" font-weight=\"bold\">A Dividend Is Not Free Money</text>\n  <text x=\"450\" y=\"57\" text-anchor=\"middle\" font-size=\"13\" fill=\"#94a3b8\">A share at 40.00 pays a dividend of 1.00. What happens on the ex-dividend date.</text>\n  <text x=\"230\" y=\"106\" text-anchor=\"middle\" font-size=\"15\" fill=\"#e2e8f0\" font-weight=\"bold\">Day before</text>\n  <rect x=\"160\" y=\"122\" width=\"140\" height=\"260\" rx=\"6\" fill=\"#3b82f6\"/>\n  <text x=\"230\" y=\"260\" text-anchor=\"middle\" font-size=\"20\" fill=\"#0f172a\" font-weight=\"bold\">40.00</text>\n  <text x=\"230\" y=\"406\" text-anchor=\"middle\" font-size=\"13\" fill=\"#94a3b8\">Share price</text>\n  <text x=\"230\" y=\"428\" text-anchor=\"middle\" font-size=\"14\" fill=\"#e2e8f0\" font-weight=\"bold\">Total held: 40.00</text>\n  <text x=\"450\" y=\"260\" text-anchor=\"middle\" font-size=\"13\" fill=\"#94a3b8\">the company pays out</text>\n  <text x=\"450\" y=\"282\" text-anchor=\"middle\" font-size=\"13\" fill=\"#94a3b8\">cash it was holding</text>\n  <text x=\"670\" y=\"106\" text-anchor=\"middle\" font-size=\"15\" fill=\"#e2e8f0\" font-weight=\"bold\">Ex-dividend date</text>\n  <rect x=\"600\" y=\"148\" width=\"140\" height=\"234\" rx=\"6\" fill=\"#3b82f6\"/>\n  <text x=\"670\" y=\"270\" text-anchor=\"middle\" font-size=\"20\" fill=\"#0f172a\" font-weight=\"bold\">39.00</text>\n  <rect x=\"600\" y=\"122\" width=\"140\" height=\"22\" rx=\"4\" fill=\"#22c55e\"/>\n  <text x=\"670\" y=\"138\" text-anchor=\"middle\" font-size=\"12\" fill=\"#0f172a\" font-weight=\"bold\">1.00 cash</text>\n  <text x=\"670\" y=\"406\" text-anchor=\"middle\" font-size=\"13\" fill=\"#94a3b8\">Share price plus the payment</text>\n  <text x=\"670\" y=\"428\" text-anchor=\"middle\" font-size=\"14\" fill=\"#e2e8f0\" font-weight=\"bold\">Total held: 40.00</text>\n  <line x1=\"60\" y1=\"456\" x2=\"840\" y2=\"456\" stroke=\"#334155\" stroke-width=\"1\"/>\n  <text x=\"450\" y=\"488\" text-anchor=\"middle\" font-size=\"14\" fill=\"#facc15\" font-weight=\"bold\">The same 40.00, rearranged. Nothing was created, and the arrangement is what feels different.</text>\n  <text x=\"450\" y=\"514\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">Judge a holding on total return, which counts price and dividends together. Not on yield alone.</text>\n</svg>",
  "stocks-01-7-fee-compounding": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 560\" font-family=\"Arial, Helvetica, sans-serif\" role=\"img\">\n  <rect x=\"0\" y=\"0\" width=\"900\" height=\"560\" fill=\"#0f172a\"/>\n  <text x=\"450\" y=\"34\" text-anchor=\"middle\" font-size=\"21\" fill=\"#e2e8f0\" font-weight=\"bold\">What an Annual Fee Does Over Thirty Years</text>\n  <text x=\"450\" y=\"57\" text-anchor=\"middle\" font-size=\"13\" fill=\"#94a3b8\">10,000 invested at an underlying 7% a year. The only difference between the three lines is the fee.</text>\n  <line x1=\"100\" y1=\"100\" x2=\"800\" y2=\"100\" stroke=\"#334155\" stroke-width=\"1\" stroke-dasharray=\"3 5\"/>\n  <text x=\"90\" y=\"104\" text-anchor=\"end\" font-size=\"12\" fill=\"#94a3b8\">80k</text>\n  <line x1=\"100\" y1=\"175\" x2=\"800\" y2=\"175\" stroke=\"#334155\" stroke-width=\"1\" stroke-dasharray=\"3 5\"/>\n  <text x=\"90\" y=\"179\" text-anchor=\"end\" font-size=\"12\" fill=\"#94a3b8\">60k</text>\n  <line x1=\"100\" y1=\"250\" x2=\"800\" y2=\"250\" stroke=\"#334155\" stroke-width=\"1\" stroke-dasharray=\"3 5\"/>\n  <text x=\"90\" y=\"254\" text-anchor=\"end\" font-size=\"12\" fill=\"#94a3b8\">40k</text>\n  <line x1=\"100\" y1=\"325\" x2=\"800\" y2=\"325\" stroke=\"#334155\" stroke-width=\"1\" stroke-dasharray=\"3 5\"/>\n  <text x=\"90\" y=\"329\" text-anchor=\"end\" font-size=\"12\" fill=\"#94a3b8\">20k</text>\n  <line x1=\"100\" y1=\"400\" x2=\"800\" y2=\"400\" stroke=\"#334155\" stroke-width=\"1\"/>\n  <text x=\"90\" y=\"404\" text-anchor=\"end\" font-size=\"12\" fill=\"#94a3b8\">0</text>\n  <text x=\"100\" y=\"422\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">0</text>\n  <text x=\"216.66666666666669\" y=\"422\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">5</text>\n  <text x=\"333.33333333333337\" y=\"422\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">10</text>\n  <text x=\"450\" y=\"422\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">15</text>\n  <text x=\"566.6666666666667\" y=\"422\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">20</text>\n  <text x=\"683.3333333333334\" y=\"422\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">25</text>\n  <text x=\"800\" y=\"422\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">30 years</text>\n  <polyline points=\"100.0,362.5 216.7,347.5 333.3,326.6 450.0,297.3 566.7,256.2 683.3,198.8 800.0,118.5\" fill=\"none\" stroke=\"#22c55e\" stroke-width=\"3\"/>\n  <text x=\"808\" y=\"122.51374999999996\" text-anchor=\"start\" font-size=\"12\" fill=\"#4ade80\" font-weight=\"bold\">0.05%</text>\n  <polyline points=\"100.0,362.5 216.7,349.2 333.3,331.2 450.0,306.9 566.7,273.9 683.3,229.3 800.0,168.8\" fill=\"none\" stroke=\"#eab308\" stroke-width=\"3\"/>\n  <text x=\"808\" y=\"172.84625\" text-anchor=\"start\" font-size=\"12\" fill=\"#facc15\" font-weight=\"bold\">0.75%</text>\n  <polyline points=\"100.0,362.5 216.7,351.0 333.3,335.9 450.0,316.3 566.7,290.6 683.3,257.0 800.0,213.1\" fill=\"none\" stroke=\"#ef4444\" stroke-width=\"3\"/>\n  <text x=\"808\" y=\"217.1\" text-anchor=\"start\" font-size=\"12\" fill=\"#f87171\" font-weight=\"bold\">1.50%</text>\n  <text x=\"450\" y=\"466\" text-anchor=\"middle\" font-size=\"14\" fill=\"#e2e8f0\" font-weight=\"bold\">At 0.05%: about 75,063   ·   at 0.75%: about 61,641   ·   at 1.50%: about 49,840</text>\n  <text x=\"450\" y=\"496\" text-anchor=\"middle\" font-size=\"13\" fill=\"#facc15\" font-weight=\"bold\">The difference in fee is 1.45% a year. The difference in outcome is about 25,200.</text>\n  <text x=\"450\" y=\"520\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">The fee is charged on the whole balance every year, including on the gains earlier fees prevented.</text>\n</svg>",
  "stocks-02-1-three-statements": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 560\" font-family=\"Arial, Helvetica, sans-serif\" role=\"img\">\n  <rect x=\"0\" y=\"0\" width=\"900\" height=\"560\" fill=\"#0f172a\"/>\n  <text x=\"450\" y=\"34\" text-anchor=\"middle\" font-size=\"21\" fill=\"#e2e8f0\" font-weight=\"bold\">Three Statements, Three Different Questions</text>\n  <text x=\"450\" y=\"57\" text-anchor=\"middle\" font-size=\"13\" fill=\"#94a3b8\">Beginners read one of them. Reading all three is what separates a view from a guess.</text>\n  <rect x=\"30\" y=\"84\" width=\"265.3333333333333\" height=\"430\" rx=\"10\" fill=\"#0f172a\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n  <text x=\"162.66666666666666\" y=\"114\" text-anchor=\"middle\" font-size=\"16\" fill=\"#60a5fa\" font-weight=\"bold\">Income statement</text>\n  <text x=\"46\" y=\"146\" text-anchor=\"start\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">Was the business profitable over</text>\n  <text x=\"46\" y=\"165\" text-anchor=\"start\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">these months?</text>\n  <text x=\"46\" y=\"202\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">Revenue is recorded when it is</text>\n  <text x=\"46\" y=\"221\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">earned, not when it is paid.</text>\n  <text x=\"46\" y=\"258\" text-anchor=\"start\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">Involves judgement.</text>\n  <text x=\"46\" y=\"285\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">How fast to depreciate equipment,</text>\n  <text x=\"46\" y=\"304\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">when a sale counts as made, how much</text>\n  <text x=\"46\" y=\"323\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">to set aside for bad debts.</text>\n  <text x=\"46\" y=\"360\" text-anchor=\"start\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">Profit is an opinion.</text>\n  <rect x=\"317.3333333333333\" y=\"84\" width=\"265.3333333333333\" height=\"430\" rx=\"10\" fill=\"#0f172a\" stroke=\"#eab308\" stroke-width=\"2\"/>\n  <text x=\"450\" y=\"114\" text-anchor=\"middle\" font-size=\"16\" fill=\"#facc15\" font-weight=\"bold\">Balance sheet</text>\n  <text x=\"333.3333333333333\" y=\"146\" text-anchor=\"start\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">What does the business consist of</text>\n  <text x=\"333.3333333333333\" y=\"165\" text-anchor=\"start\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">right now?</text>\n  <text x=\"333.3333333333333\" y=\"202\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">A single moment, not a period.</text>\n  <text x=\"333.3333333333333\" y=\"221\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">Assets equal liabilities plus</text>\n  <text x=\"333.3333333333333\" y=\"240\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">equity, by identity.</text>\n  <text x=\"333.3333333333333\" y=\"277\" text-anchor=\"start\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">Equity is the residual again.</text>\n  <text x=\"333.3333333333333\" y=\"304\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">Assets 500, owed 400, equity 100.</text>\n  <text x=\"333.3333333333333\" y=\"323\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">Write the assets down to 380 and the</text>\n  <text x=\"333.3333333333333\" y=\"342\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">equity is gone.</text>\n  <text x=\"333.3333333333333\" y=\"379\" text-anchor=\"start\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">This is Lesson 1 from another angle.</text>\n  <rect x=\"604.6666666666666\" y=\"84\" width=\"265.3333333333333\" height=\"430\" rx=\"10\" fill=\"#0f172a\" stroke=\"#22c55e\" stroke-width=\"2\"/>\n  <text x=\"737.3333333333333\" y=\"114\" text-anchor=\"middle\" font-size=\"16\" fill=\"#4ade80\" font-weight=\"bold\">Cash flow statement</text>\n  <text x=\"620.6666666666666\" y=\"146\" text-anchor=\"start\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">Did money genuinely move?</text>\n  <text x=\"620.6666666666666\" y=\"183\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">Hardest of the three to dress up,</text>\n  <text x=\"620.6666666666666\" y=\"202\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">because cash either arrived or it</text>\n  <text x=\"620.6666666666666\" y=\"221\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">did not.</text>\n  <text x=\"620.6666666666666\" y=\"258\" text-anchor=\"start\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">Free cash flow is the owner's</text>\n  <text x=\"620.6666666666666\" y=\"277\" text-anchor=\"start\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">number.</text>\n  <text x=\"620.6666666666666\" y=\"304\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">Operating cash less the spending</text>\n  <text x=\"620.6666666666666\" y=\"323\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">needed to keep the business running.</text>\n  <text x=\"620.6666666666666\" y=\"360\" text-anchor=\"start\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">Cash is a fact.</text>\n</svg>",
  "stocks-02-2-cyclical-multiple": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 560\" font-family=\"Arial, Helvetica, sans-serif\" role=\"img\">\n  <rect x=\"0\" y=\"0\" width=\"900\" height=\"560\" fill=\"#0f172a\"/>\n  <text x=\"450\" y=\"34\" text-anchor=\"middle\" font-size=\"21\" fill=\"#e2e8f0\" font-weight=\"bold\">Why a Low Multiple Is Most Dangerous When It Looks Best</text>\n  <text x=\"450\" y=\"57\" text-anchor=\"middle\" font-size=\"13\" fill=\"#94a3b8\">A cyclical company through one commodity cycle. Earnings move; the multiple moves against them.</text>\n  <line x1=\"90\" y1=\"100\" x2=\"730\" y2=\"100\" stroke=\"#334155\" stroke-width=\"1\" stroke-dasharray=\"3 5\"/>\n  <text x=\"80\" y=\"104\" text-anchor=\"end\" font-size=\"12\" fill=\"#94a3b8\">6.0</text>\n  <line x1=\"90\" y1=\"150\" x2=\"730\" y2=\"150\" stroke=\"#334155\" stroke-width=\"1\" stroke-dasharray=\"3 5\"/>\n  <text x=\"80\" y=\"154\" text-anchor=\"end\" font-size=\"12\" fill=\"#94a3b8\">4.0</text>\n  <line x1=\"90\" y1=\"200\" x2=\"730\" y2=\"200\" stroke=\"#334155\" stroke-width=\"1\" stroke-dasharray=\"3 5\"/>\n  <text x=\"80\" y=\"204\" text-anchor=\"end\" font-size=\"12\" fill=\"#94a3b8\">2.0</text>\n  <line x1=\"90\" y1=\"250\" x2=\"730\" y2=\"250\" stroke=\"#334155\" stroke-width=\"1\"/>\n  <text x=\"80\" y=\"254\" text-anchor=\"end\" font-size=\"12\" fill=\"#94a3b8\">0.0</text>\n  <text x=\"90\" y=\"272\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">year 1</text>\n  <text x=\"196.66666666666669\" y=\"272\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">2</text>\n  <text x=\"303.33333333333337\" y=\"272\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">3</text>\n  <text x=\"410\" y=\"272\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">4</text>\n  <text x=\"516.6666666666667\" y=\"272\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">5</text>\n  <text x=\"623.3333333333334\" y=\"272\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">6</text>\n  <text x=\"730\" y=\"272\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">7</text>\n  <polyline points=\"90.0,225.0 196.7,190.0 303.3,145.0 410.0,125.0 516.7,175.0 623.3,220.0 730.0,237.5\" fill=\"none\" stroke=\"#22c55e\" stroke-width=\"3\"/>\n  <text x=\"738\" y=\"241.5\" text-anchor=\"start\" font-size=\"12\" fill=\"#4ade80\" font-weight=\"bold\">Earnings per share</text>\n  <line x1=\"90\" y1=\"310\" x2=\"730\" y2=\"310\" stroke=\"#334155\" stroke-width=\"1\" stroke-dasharray=\"3 5\"/>\n  <text x=\"80\" y=\"314\" text-anchor=\"end\" font-size=\"12\" fill=\"#94a3b8\">45</text>\n  <line x1=\"90\" y1=\"360\" x2=\"730\" y2=\"360\" stroke=\"#334155\" stroke-width=\"1\" stroke-dasharray=\"3 5\"/>\n  <text x=\"80\" y=\"364\" text-anchor=\"end\" font-size=\"12\" fill=\"#94a3b8\">30</text>\n  <line x1=\"90\" y1=\"410\" x2=\"730\" y2=\"410\" stroke=\"#334155\" stroke-width=\"1\" stroke-dasharray=\"3 5\"/>\n  <text x=\"80\" y=\"414\" text-anchor=\"end\" font-size=\"12\" fill=\"#94a3b8\">15</text>\n  <line x1=\"90\" y1=\"460\" x2=\"730\" y2=\"460\" stroke=\"#334155\" stroke-width=\"1\"/>\n  <text x=\"80\" y=\"464\" text-anchor=\"end\" font-size=\"12\" fill=\"#94a3b8\">0</text>\n  <text x=\"90\" y=\"482\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">year 1</text>\n  <text x=\"196.66666666666669\" y=\"482\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">2</text>\n  <text x=\"303.33333333333337\" y=\"482\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">3</text>\n  <text x=\"410\" y=\"482\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">4</text>\n  <text x=\"516.6666666666667\" y=\"482\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">5</text>\n  <text x=\"623.3333333333334\" y=\"482\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">6</text>\n  <text x=\"730\" y=\"482\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">7</text>\n  <polyline points=\"90.0,360.0 196.7,413.3 303.3,433.3 410.0,440.0 516.7,423.3 623.3,373.3 730.0,326.7\" fill=\"none\" stroke=\"#ef4444\" stroke-width=\"3\"/>\n  <text x=\"738\" y=\"330.6666666666667\" text-anchor=\"start\" font-size=\"12\" fill=\"#f87171\" font-weight=\"bold\">Price to earnings</text>\n  <line x1=\"410\" y1=\"100\" x2=\"410\" y2=\"460\" stroke=\"#eab308\" stroke-width=\"2\" stroke-dasharray=\"5 5\"/>\n  <text x=\"418\" y=\"96\" text-anchor=\"start\" font-size=\"12\" fill=\"#facc15\" font-weight=\"bold\">peak earnings, lowest multiple</text>\n  <text x=\"450\" y=\"512\" text-anchor=\"middle\" font-size=\"14\" fill=\"#e2e8f0\" font-weight=\"bold\">The P/E of 6 in year 4 marked the danger. The P/E of 40 in year 7 marked the opportunity.</text>\n  <text x=\"450\" y=\"536\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">A screen for the lowest multiples buys the top of the cycle. Ask where in the cycle the earnings sit.</text>\n</svg>",
  "stocks-02-3-value-definitions": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 560\" font-family=\"Arial, Helvetica, sans-serif\" role=\"img\">\n  <rect x=\"0\" y=\"0\" width=\"900\" height=\"560\" fill=\"#0f172a\"/>\n  <text x=\"450\" y=\"34\" text-anchor=\"middle\" font-size=\"21\" fill=\"#e2e8f0\" font-weight=\"bold\">Which \"Value\"? The Definition Is a Choice</text>\n  <text x=\"450\" y=\"57\" text-anchor=\"middle\" font-size=\"13\" fill=\"#94a3b8\">Three measures of cheapness, selecting overlapping but genuinely different companies.</text>\n  <circle cx=\"360\" cy=\"270\" r=\"130\" fill=\"#3b82f6\" fill-opacity=\"0.28\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n  <circle cx=\"500\" cy=\"230\" r=\"130\" fill=\"#22c55e\" fill-opacity=\"0.28\" stroke=\"#22c55e\" stroke-width=\"2\"/>\n  <circle cx=\"470\" cy=\"360\" r=\"120\" fill=\"#eab308\" fill-opacity=\"0.24\" stroke=\"#eab308\" stroke-width=\"2\"/>\n  <text x=\"280\" y=\"250\" text-anchor=\"middle\" font-size=\"14\" fill=\"#60a5fa\" font-weight=\"bold\">Book to market</text>\n  <text x=\"280\" y=\"270\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">(Fama and French)</text>\n  <text x=\"590\" y=\"190\" text-anchor=\"middle\" font-size=\"14\" fill=\"#4ade80\" font-weight=\"bold\">Earnings</text>\n  <text x=\"470\" y=\"452\" text-anchor=\"middle\" font-size=\"14\" fill=\"#facc15\" font-weight=\"bold\">Cash flow</text>\n  <text x=\"430\" y=\"288\" text-anchor=\"middle\" font-size=\"12\" fill=\"#e2e8f0\" font-weight=\"bold\">all three</text>\n  <rect x=\"660\" y=\"110\" width=\"210\" height=\"200\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\" stroke-width=\"2\"/>\n  <text x=\"765\" y=\"138\" text-anchor=\"middle\" font-size=\"14\" fill=\"#e2e8f0\" font-weight=\"bold\">And then</text>\n  <text x=\"675\" y=\"162\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">Book value describes a</text>\n  <text x=\"675\" y=\"178\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">factory well and software</text>\n  <text x=\"675\" y=\"194\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">badly.</text>\n  <text x=\"675\" y=\"226\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">A fund calling itself a</text>\n  <text x=\"675\" y=\"242\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">value fund need not use</text>\n  <text x=\"675\" y=\"258\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">the measure the study</text>\n  <text x=\"675\" y=\"274\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">used.</text>\n  <text x=\"675\" y=\"306\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">Costs are subtracted from</text>\n  <text x=\"675\" y=\"322\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">the premium, not from</text>\n  <text x=\"675\" y=\"338\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">somewhere else.</text>\n  <text x=\"450\" y=\"508\" text-anchor=\"middle\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">A finding about one definition of value is not automatically a finding about the fund on your screen.</text>\n  <text x=\"450\" y=\"532\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">Fama and French 1992 measured book-to-market across large baskets over decades. Ask what your fund measures.</text>\n</svg>",
  "stocks-02-4-efficiency-forms": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 560\" font-family=\"Arial, Helvetica, sans-serif\" role=\"img\">\n  <rect x=\"0\" y=\"0\" width=\"900\" height=\"560\" fill=\"#0f172a\"/>\n  <text x=\"450\" y=\"34\" text-anchor=\"middle\" font-size=\"21\" fill=\"#e2e8f0\" font-weight=\"bold\">Three Forms of Efficiency, and the Paradox Underneath</text>\n  <text x=\"450\" y=\"57\" text-anchor=\"middle\" font-size=\"13\" fill=\"#94a3b8\">Each form contains the one before it. The strongest cannot exist.</text>\n  <rect x=\"70\" y=\"92\" width=\"500\" height=\"340\" rx=\"10\" fill=\"#0f172a\" stroke=\"#ef4444\" stroke-width=\"2\"/>\n  <text x=\"90\" y=\"118\" text-anchor=\"start\" font-size=\"14\" fill=\"#f87171\" font-weight=\"bold\">Strong form: all information, including private</text>\n  <rect x=\"96\" y=\"136\" width=\"448\" height=\"274\" rx=\"10\" fill=\"#0f172a\" stroke=\"#eab308\" stroke-width=\"2\"/>\n  <text x=\"116\" y=\"162\" text-anchor=\"start\" font-size=\"14\" fill=\"#facc15\" font-weight=\"bold\">Semi-strong: all public information</text>\n  <rect x=\"122\" y=\"180\" width=\"396\" height=\"208\" rx=\"10\" fill=\"#0f172a\" stroke=\"#22c55e\" stroke-width=\"2\"/>\n  <text x=\"142\" y=\"206\" text-anchor=\"start\" font-size=\"14\" fill=\"#4ade80\" font-weight=\"bold\">Weak form: past prices</text>\n  <text x=\"142\" y=\"236\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">Studying price history alone cannot</text>\n  <text x=\"142\" y=\"254\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">produce an edge.</text>\n  <text x=\"142\" y=\"288\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">Results announced at 07:00 have moved</text>\n  <text x=\"142\" y=\"306\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">the price before the market opens.</text>\n  <text x=\"142\" y=\"344\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">Trading on material private information</text>\n  <text x=\"142\" y=\"362\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">works, and is illegal everywhere.</text>\n  <rect x=\"596\" y=\"92\" width=\"260\" height=\"340\" rx=\"10\" fill=\"#0f172a\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n  <text x=\"726\" y=\"120\" text-anchor=\"middle\" font-size=\"14\" fill=\"#60a5fa\" font-weight=\"bold\">Grossman and Stiglitz, 1980</text>\n  <text x=\"612\" y=\"152\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">Gathering information costs</text>\n  <text x=\"612\" y=\"169\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">money.</text>\n  <text x=\"612\" y=\"202\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">If prices already reflected</text>\n  <text x=\"612\" y=\"219\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">everything, nobody would be</text>\n  <text x=\"612\" y=\"236\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">paid for gathering it.</text>\n  <text x=\"612\" y=\"269\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">So nobody would gather it, and</text>\n  <text x=\"612\" y=\"286\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">prices would stop reflecting</text>\n  <text x=\"612\" y=\"303\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">it.</text>\n  <text x=\"612\" y=\"336\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">Some inefficiency has to</text>\n  <text x=\"612\" y=\"353\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">persist, as the payment for</text>\n  <text x=\"612\" y=\"370\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">the work.</text>\n  <text x=\"450\" y=\"476\" text-anchor=\"middle\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">Efficiency is a spectrum, not a switch — and it means prices reflect information, not that they are right.</text>\n  <text x=\"450\" y=\"502\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">The argument does not tell you that you are the one collecting the payment. Sharpe's arithmetic says most are not.</text>\n  <text x=\"450\" y=\"528\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">A private investor's real advantage is structural: no clients, no quarterly report, no career risk from waiting.</text>\n</svg>",
  "stocks-02-5-diversification-floor": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 560\" font-family=\"Arial, Helvetica, sans-serif\" role=\"img\">\n  <rect x=\"0\" y=\"0\" width=\"900\" height=\"560\" fill=\"#0f172a\"/>\n  <text x=\"450\" y=\"34\" text-anchor=\"middle\" font-size=\"21\" fill=\"#e2e8f0\" font-weight=\"bold\">How Many Holdings Is Enough? The Literature Disagrees</text>\n  <text x=\"450\" y=\"57\" text-anchor=\"middle\" font-size=\"13\" fill=\"#94a3b8\">Adding holdings removes specific risk. It does nothing at all to market risk.</text>\n  <line x1=\"90\" y1=\"100\" x2=\"790\" y2=\"100\" stroke=\"#334155\" stroke-width=\"1\" stroke-dasharray=\"3 5\"/>\n  <text x=\"80\" y=\"104\" text-anchor=\"end\" font-size=\"12\" fill=\"#94a3b8\">100</text>\n  <line x1=\"90\" y1=\"170\" x2=\"790\" y2=\"170\" stroke=\"#334155\" stroke-width=\"1\" stroke-dasharray=\"3 5\"/>\n  <text x=\"80\" y=\"174\" text-anchor=\"end\" font-size=\"12\" fill=\"#94a3b8\">75</text>\n  <line x1=\"90\" y1=\"240\" x2=\"790\" y2=\"240\" stroke=\"#334155\" stroke-width=\"1\" stroke-dasharray=\"3 5\"/>\n  <text x=\"80\" y=\"244\" text-anchor=\"end\" font-size=\"12\" fill=\"#94a3b8\">50</text>\n  <line x1=\"90\" y1=\"310\" x2=\"790\" y2=\"310\" stroke=\"#334155\" stroke-width=\"1\" stroke-dasharray=\"3 5\"/>\n  <text x=\"80\" y=\"314\" text-anchor=\"end\" font-size=\"12\" fill=\"#94a3b8\">25</text>\n  <line x1=\"90\" y1=\"380\" x2=\"790\" y2=\"380\" stroke=\"#334155\" stroke-width=\"1\"/>\n  <text x=\"80\" y=\"384\" text-anchor=\"end\" font-size=\"12\" fill=\"#94a3b8\">0</text>\n  <text x=\"90\" y=\"402\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">1</text>\n  <text x=\"177.5\" y=\"402\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">5</text>\n  <text x=\"265\" y=\"402\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">10</text>\n  <text x=\"352.5\" y=\"402\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">15</text>\n  <text x=\"440\" y=\"402\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">20</text>\n  <text x=\"527.5\" y=\"402\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">30</text>\n  <text x=\"615\" y=\"402\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">40</text>\n  <text x=\"702.5\" y=\"402\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">50</text>\n  <text x=\"790\" y=\"402\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">60 holdings</text>\n  <polyline points=\"90.0,100.0 177.5,206.4 265.0,245.6 352.5,265.2 440.0,273.6 527.5,279.2 615.0,282.0 702.5,283.7 790.0,284.8\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"3\"/>\n  <text x=\"798\" y=\"288.8\" text-anchor=\"start\" font-size=\"12\" fill=\"#60a5fa\" font-weight=\"bold\">total risk</text>\n  <polyline points=\"90.0,287.6 177.5,287.6 265.0,287.6 352.5,287.6 440.0,287.6 527.5,287.6 615.0,287.6 702.5,287.6 790.0,287.6\" fill=\"none\" stroke=\"#ef4444\" stroke-width=\"2\" stroke-dasharray=\"6 5\"/>\n  <text x=\"798\" y=\"291.6\" text-anchor=\"start\" font-size=\"12\" fill=\"#f87171\" font-weight=\"bold\"></text>\n  <line x1=\"200\" y1=\"100\" x2=\"200\" y2=\"380\" stroke=\"#22c55e\" stroke-width=\"2\" stroke-dasharray=\"4 4\"/>\n  <text x=\"206\" y=\"126\" text-anchor=\"start\" font-size=\"12\" fill=\"#4ade80\" font-weight=\"bold\">Evans and Archer 1968: the curve flattens</text>\n  <text x=\"206\" y=\"144\" text-anchor=\"start\" font-size=\"12\" fill=\"#4ade80\" font-weight=\"bold\">by about 10 holdings</text>\n  <line x1=\"462\" y1=\"100\" x2=\"462\" y2=\"380\" stroke=\"#eab308\" stroke-width=\"2\" stroke-dasharray=\"4 4\"/>\n  <text x=\"468\" y=\"176\" text-anchor=\"start\" font-size=\"12\" fill=\"#facc15\" font-weight=\"bold\">Statman 1987: at least 30 for a borrowing</text>\n  <text x=\"468\" y=\"194\" text-anchor=\"start\" font-size=\"12\" fill=\"#facc15\" font-weight=\"bold\">investor, 40 for a lending one</text>\n  <text x=\"600\" y=\"280\" text-anchor=\"start\" font-size=\"12\" fill=\"#f87171\" font-weight=\"bold\">market risk: the floor no holding removes</text>\n  <text x=\"450\" y=\"448\" text-anchor=\"middle\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">Market risk survives every holding you add. That is the floor, and it is why the curve never reaches zero.</text>\n  <text x=\"450\" y=\"476\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">Counting is the wrong instrument anyway: twenty banks are one bet wearing twenty names.</text>\n  <text x=\"450\" y=\"502\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">The curve shape is illustrative. The two dated findings, and their disagreement, are the point.</text>\n</svg>",
  "stocks-03-1-recovery-arithmetic": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 560\" font-family=\"Arial, Helvetica, sans-serif\" role=\"img\">\n  <rect x=\"0\" y=\"0\" width=\"900\" height=\"560\" fill=\"#0f172a\"/>\n  <text x=\"450\" y=\"34\" text-anchor=\"middle\" font-size=\"21\" fill=\"#e2e8f0\" font-weight=\"bold\">The Arithmetic of Getting Back to Even</text>\n  <text x=\"450\" y=\"57\" text-anchor=\"middle\" font-size=\"13\" fill=\"#94a3b8\">The fall is measured from the peak. The recovery is measured from the much smaller trough.</text>\n  <text x=\"208\" y=\"125\" text-anchor=\"end\" font-size=\"13\" fill=\"#e2e8f0\">a fall of 20%</text>\n  <rect x=\"220\" y=\"100\" width=\"25\" height=\"40\" rx=\"3\" fill=\"#22c55e\"/>\n  <text x=\"255\" y=\"125\" text-anchor=\"start\" font-size=\"13\" fill=\"#4ade80\" font-weight=\"bold\">needs a gain of 25.0%</text>\n  <text x=\"208\" y=\"191\" text-anchor=\"end\" font-size=\"13\" fill=\"#e2e8f0\">a fall of 30%</text>\n  <rect x=\"220\" y=\"166\" width=\"42.85714285714286\" height=\"40\" rx=\"3\" fill=\"#22c55e\"/>\n  <text x=\"272.8571428571429\" y=\"191\" text-anchor=\"start\" font-size=\"13\" fill=\"#4ade80\" font-weight=\"bold\">needs a gain of 42.9%</text>\n  <text x=\"208\" y=\"257\" text-anchor=\"end\" font-size=\"13\" fill=\"#e2e8f0\">a fall of 50%</text>\n  <rect x=\"220\" y=\"232\" width=\"100\" height=\"40\" rx=\"3\" fill=\"#eab308\"/>\n  <text x=\"330\" y=\"257\" text-anchor=\"start\" font-size=\"13\" fill=\"#facc15\" font-weight=\"bold\">needs a gain of 100.0%</text>\n  <text x=\"208\" y=\"323\" text-anchor=\"end\" font-size=\"13\" fill=\"#e2e8f0\">a fall of 56.8%</text>\n  <rect x=\"220\" y=\"298\" width=\"131.37436372049973\" height=\"40\" rx=\"3\" fill=\"#eab308\"/>\n  <text x=\"361.37436372049973\" y=\"323\" text-anchor=\"start\" font-size=\"13\" fill=\"#facc15\" font-weight=\"bold\">needs a gain of 131%</text>\n  <text x=\"208\" y=\"389\" text-anchor=\"end\" font-size=\"13\" fill=\"#e2e8f0\">a fall of 77.9%</text>\n  <rect x=\"220\" y=\"364\" width=\"353.1037607612145\" height=\"40\" rx=\"3\" fill=\"#ef4444\"/>\n  <text x=\"583.1037607612145\" y=\"389\" text-anchor=\"start\" font-size=\"13\" fill=\"#f87171\" font-weight=\"bold\">needs a gain of 353%</text>\n  <line x1=\"60\" y1=\"442\" x2=\"840\" y2=\"442\" stroke=\"#334155\" stroke-width=\"1\"/>\n  <text x=\"450\" y=\"474\" text-anchor=\"middle\" font-size=\"14\" fill=\"#e2e8f0\" font-weight=\"bold\">A drawdown twice as deep takes far more than twice as much to repair.</text>\n  <text x=\"450\" y=\"500\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">56.8% is the S&amp;P 500 in 2007 to 2009. 77.9% is the Nasdaq Composite in 2000 to 2002.</text>\n  <text x=\"450\" y=\"524\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">Which is the arithmetic reason to care more about avoiding large losses than about capturing large gains.</text>\n</svg>",
  "stocks-03-2-position-sizing": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 560\" font-family=\"Arial, Helvetica, sans-serif\" role=\"img\">\n  <rect x=\"0\" y=\"0\" width=\"900\" height=\"560\" fill=\"#0f172a\"/>\n  <text x=\"450\" y=\"34\" text-anchor=\"middle\" font-size=\"21\" fill=\"#e2e8f0\" font-weight=\"bold\">The Same Bad News, at Four Different Position Sizes</text>\n  <text x=\"450\" y=\"57\" text-anchor=\"middle\" font-size=\"13\" fill=\"#94a3b8\">A company you hold falls 60%. What that costs the portfolio depends only on the size you chose.</text>\n  <text x=\"188\" y=\"134\" text-anchor=\"end\" font-size=\"13\" fill=\"#e2e8f0\">2% position</text>\n  <rect x=\"200\" y=\"108\" width=\"19.384615384615383\" height=\"42\" rx=\"3\" fill=\"#22c55e\"/>\n  <text x=\"229.3846153846154\" y=\"134\" text-anchor=\"start\" font-size=\"13\" fill=\"#4ade80\" font-weight=\"bold\">portfolio down 1.2% — an ordinary week</text>\n  <text x=\"188\" y=\"204\" text-anchor=\"end\" font-size=\"13\" fill=\"#e2e8f0\">10% position</text>\n  <rect x=\"200\" y=\"178\" width=\"96.92307692307693\" height=\"42\" rx=\"3\" fill=\"#eab308\"/>\n  <text x=\"306.9230769230769\" y=\"204\" text-anchor=\"start\" font-size=\"13\" fill=\"#facc15\" font-weight=\"bold\">portfolio down 6% — a bad month</text>\n  <text x=\"188\" y=\"274\" text-anchor=\"end\" font-size=\"13\" fill=\"#e2e8f0\">25% position</text>\n  <rect x=\"200\" y=\"248\" width=\"242.3076923076923\" height=\"42\" rx=\"3\" fill=\"#ef4444\"/>\n  <text x=\"452.30769230769226\" y=\"274\" text-anchor=\"start\" font-size=\"13\" fill=\"#f87171\" font-weight=\"bold\">portfolio down 15% — a bad year</text>\n  <text x=\"188\" y=\"344\" text-anchor=\"end\" font-size=\"13\" fill=\"#e2e8f0\">40% position</text>\n  <rect x=\"200\" y=\"318\" width=\"387.69230769230774\" height=\"42\" rx=\"3\" fill=\"#ef4444\"/>\n  <text x=\"597.6923076923077\" y=\"344\" text-anchor=\"start\" font-size=\"13\" fill=\"#f87171\" font-weight=\"bold\">portfolio down 24% — a changed plan</text>\n  <line x1=\"60\" y1=\"400\" x2=\"840\" y2=\"400\" stroke=\"#334155\" stroke-width=\"1\"/>\n  <text x=\"450\" y=\"434\" text-anchor=\"middle\" font-size=\"14\" fill=\"#e2e8f0\" font-weight=\"bold\">You cannot control whether a company disappoints. You control this number completely, in advance.</text>\n  <rect x=\"150\" y=\"452\" width=\"600\" height=\"76\" rx=\"8\" fill=\"#0f172a\" stroke=\"#eab308\" stroke-width=\"2\"/>\n  <text x=\"450\" y=\"478\" text-anchor=\"middle\" font-size=\"13\" fill=\"#facc15\" font-weight=\"bold\">And a limit only survives success if it is maintained</text>\n  <text x=\"450\" y=\"502\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">A 2% holding that rises fivefold while everything else is flat becomes about 9% of the portfolio.</text>\n  <text x=\"450\" y=\"520\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">Nobody chose the 9%. Drift is how most large concentrations are actually acquired.</text>\n</svg>",
  "stocks-03-3-dca-both-directions": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 560\" font-family=\"Arial, Helvetica, sans-serif\" role=\"img\">\n  <rect x=\"0\" y=\"0\" width=\"900\" height=\"560\" fill=\"#0f172a\"/>\n  <text x=\"450\" y=\"34\" text-anchor=\"middle\" font-size=\"21\" fill=\"#e2e8f0\" font-weight=\"bold\">Averaging In Wins When Prices Fall, and Loses When They Rise</text>\n  <text x=\"450\" y=\"57\" text-anchor=\"middle\" font-size=\"13\" fill=\"#94a3b8\">12,000 deployed either at once or in twelve monthly instalments of 1,000.</text>\n  <text x=\"240\" y=\"96\" text-anchor=\"middle\" font-size=\"14\" fill=\"#e2e8f0\" font-weight=\"bold\">Prices fall, then recover to 105</text>\n  <line x1=\"90\" y1=\"116\" x2=\"390\" y2=\"116\" stroke=\"#334155\" stroke-width=\"1\" stroke-dasharray=\"3 5\"/>\n  <text x=\"80\" y=\"120\" text-anchor=\"end\" font-size=\"12\" fill=\"#94a3b8\">120</text>\n  <line x1=\"90\" y1=\"191\" x2=\"390\" y2=\"191\" stroke=\"#334155\" stroke-width=\"1\" stroke-dasharray=\"3 5\"/>\n  <text x=\"80\" y=\"195\" text-anchor=\"end\" font-size=\"12\" fill=\"#94a3b8\">90</text>\n  <line x1=\"90\" y1=\"266\" x2=\"390\" y2=\"266\" stroke=\"#334155\" stroke-width=\"1\"/>\n  <text x=\"80\" y=\"270\" text-anchor=\"end\" font-size=\"12\" fill=\"#94a3b8\">60</text>\n  <text x=\"90\" y=\"288\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">month 1</text>\n  <text x=\"240\" y=\"288\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">6</text>\n  <text x=\"390\" y=\"288\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">12</text>\n  <polyline points=\"90.0,166.0 117.3,178.5 144.5,191.0 171.8,203.5 199.1,216.0 226.4,228.5 253.6,216.0 280.9,203.5 308.2,191.0 335.5,178.5 362.7,166.0 390.0,153.5\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"3\"/>\n  <text x=\"398\" y=\"157.5\" text-anchor=\"start\" font-size=\"12\" fill=\"#3b82f6\" font-weight=\"bold\"></text>\n  <text x=\"660\" y=\"96\" text-anchor=\"middle\" font-size=\"14\" fill=\"#e2e8f0\" font-weight=\"bold\">Prices rise steadily to 122</text>\n  <line x1=\"510\" y1=\"116\" x2=\"810\" y2=\"116\" stroke=\"#334155\" stroke-width=\"1\" stroke-dasharray=\"3 5\"/>\n  <text x=\"500\" y=\"120\" text-anchor=\"end\" font-size=\"12\" fill=\"#94a3b8\">130</text>\n  <line x1=\"510\" y1=\"191\" x2=\"810\" y2=\"191\" stroke=\"#334155\" stroke-width=\"1\" stroke-dasharray=\"3 5\"/>\n  <text x=\"500\" y=\"195\" text-anchor=\"end\" font-size=\"12\" fill=\"#94a3b8\">110</text>\n  <line x1=\"510\" y1=\"266\" x2=\"810\" y2=\"266\" stroke=\"#334155\" stroke-width=\"1\"/>\n  <text x=\"500\" y=\"270\" text-anchor=\"end\" font-size=\"12\" fill=\"#94a3b8\">90</text>\n  <text x=\"510\" y=\"288\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">month 1</text>\n  <text x=\"660\" y=\"288\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">6</text>\n  <text x=\"810\" y=\"288\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">12</text>\n  <polyline points=\"510.0,228.5 537.3,221.0 564.5,213.5 591.8,206.0 619.1,198.5 646.4,191.0 673.6,183.5 700.9,176.0 728.2,168.5 755.5,161.0 782.7,153.5 810.0,146.0\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"3\"/>\n  <text x=\"818\" y=\"150\" text-anchor=\"start\" font-size=\"12\" fill=\"#3b82f6\" font-weight=\"bold\"></text>\n  <text x=\"288\" y=\"340\" text-anchor=\"end\" font-size=\"13\" fill=\"#e2e8f0\">averaging in, falling market</text>\n  <rect x=\"300\" y=\"322\" width=\"346.63354838709677\" height=\"26\" rx=\"3\" fill=\"#22c55e\"/>\n  <text x=\"656.6335483870968\" y=\"340\" text-anchor=\"start\" font-size=\"13\" fill=\"#4ade80\" font-weight=\"bold\">14,139</text>\n  <text x=\"288\" y=\"378\" text-anchor=\"end\" font-size=\"13\" fill=\"#e2e8f0\">all at once, falling market</text>\n  <rect x=\"300\" y=\"360\" width=\"308.9032258064516\" height=\"26\" rx=\"3\" fill=\"#94a3b8\"/>\n  <text x=\"618.9032258064516\" y=\"378\" text-anchor=\"start\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">12,600</text>\n  <text x=\"288\" y=\"416\" text-anchor=\"end\" font-size=\"13\" fill=\"#e2e8f0\">averaging in, rising market</text>\n  <rect x=\"300\" y=\"398\" width=\"324.61806451612904\" height=\"26\" rx=\"3\" fill=\"#ef4444\"/>\n  <text x=\"634.618064516129\" y=\"416\" text-anchor=\"start\" font-size=\"13\" fill=\"#f87171\" font-weight=\"bold\">13,241</text>\n  <text x=\"288\" y=\"454\" text-anchor=\"end\" font-size=\"13\" fill=\"#e2e8f0\">all at once, rising market</text>\n  <rect x=\"300\" y=\"436\" width=\"358.916129032258\" height=\"26\" rx=\"3\" fill=\"#94a3b8\"/>\n  <text x=\"668.916129032258\" y=\"454\" text-anchor=\"start\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">14,640</text>\n  <text x=\"450\" y=\"500\" text-anchor=\"middle\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">Neither outcome was knowable at the start, and markets rise more often than they fall.</text>\n  <text x=\"450\" y=\"524\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">That is where the two-thirds finding comes from. Averaging in buys a behavioural guarantee at a known cost.</text>\n</svg>",
  "stocks-03-4-margin-call": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 560\" font-family=\"Arial, Helvetica, sans-serif\" role=\"img\">\n  <rect x=\"0\" y=\"0\" width=\"900\" height=\"560\" fill=\"#0f172a\"/>\n  <text x=\"450\" y=\"34\" text-anchor=\"middle\" font-size=\"21\" fill=\"#e2e8f0\" font-weight=\"bold\">How Far a Margined Position Has to Fall Before It Is Closed for You</text>\n  <text x=\"450\" y=\"57\" text-anchor=\"middle\" font-size=\"13\" fill=\"#94a3b8\">10,000 of your own money, 10,000 borrowed, 20,000 of shares, 25% maintenance requirement.</text>\n  <line x1=\"100\" y1=\"110\" x2=\"760\" y2=\"110\" stroke=\"#334155\" stroke-width=\"1\" stroke-dasharray=\"3 5\"/>\n  <text x=\"90\" y=\"114\" text-anchor=\"end\" font-size=\"12\" fill=\"#94a3b8\">10k</text>\n  <line x1=\"100\" y1=\"175\" x2=\"760\" y2=\"175\" stroke=\"#334155\" stroke-width=\"1\" stroke-dasharray=\"3 5\"/>\n  <text x=\"90\" y=\"179\" text-anchor=\"end\" font-size=\"12\" fill=\"#94a3b8\">8k</text>\n  <line x1=\"100\" y1=\"240\" x2=\"760\" y2=\"240\" stroke=\"#334155\" stroke-width=\"1\" stroke-dasharray=\"3 5\"/>\n  <text x=\"90\" y=\"244\" text-anchor=\"end\" font-size=\"12\" fill=\"#94a3b8\">5k</text>\n  <line x1=\"100\" y1=\"305\" x2=\"760\" y2=\"305\" stroke=\"#334155\" stroke-width=\"1\" stroke-dasharray=\"3 5\"/>\n  <text x=\"90\" y=\"309\" text-anchor=\"end\" font-size=\"12\" fill=\"#94a3b8\">3k</text>\n  <line x1=\"100\" y1=\"370\" x2=\"760\" y2=\"370\" stroke=\"#334155\" stroke-width=\"1\"/>\n  <text x=\"90\" y=\"374\" text-anchor=\"end\" font-size=\"12\" fill=\"#94a3b8\">0k</text>\n  <text x=\"100\" y=\"392\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">0%</text>\n  <text x=\"182.5\" y=\"392\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\"></text>\n  <text x=\"265\" y=\"392\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">-10%</text>\n  <text x=\"347.5\" y=\"392\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\"></text>\n  <text x=\"430\" y=\"392\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">-20%</text>\n  <text x=\"512.5\" y=\"392\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\"></text>\n  <text x=\"595\" y=\"392\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">-30%</text>\n  <text x=\"677.5\" y=\"392\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\"></text>\n  <text x=\"760\" y=\"392\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">-40%</text>\n  <polyline points=\"100.0,110.0 182.5,136.0 265.0,162.0 347.5,188.0 430.0,214.0 512.5,240.0 595.0,266.0 677.5,292.0 760.0,318.0\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"3\"/>\n  <text x=\"768\" y=\"322\" text-anchor=\"start\" font-size=\"12\" fill=\"#60a5fa\" font-weight=\"bold\">your money</text>\n  <line x1=\"100\" y1=\"370\" x2=\"760\" y2=\"370\" stroke=\"#334155\" stroke-width=\"2\"/>\n  <line x1=\"540\" y1=\"110\" x2=\"540\" y2=\"370\" stroke=\"#ef4444\" stroke-width=\"2\" stroke-dasharray=\"5 5\"/>\n  <text x=\"548\" y=\"140\" text-anchor=\"start\" font-size=\"13\" fill=\"#f87171\" font-weight=\"bold\">margin call at a fall of about 33%</text>\n  <text x=\"548\" y=\"160\" text-anchor=\"start\" font-size=\"12\" fill=\"#f87171\">position worth 13,333, your money 3,333</text>\n  <text x=\"548\" y=\"178\" text-anchor=\"start\" font-size=\"12\" fill=\"#f87171\">a 33% fall in the shares, a 67% loss for you</text>\n  <text x=\"430\" y=\"412\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">fall in the share price</text>\n  <line x1=\"60\" y1=\"424\" x2=\"840\" y2=\"424\" stroke=\"#334155\" stroke-width=\"1\"/>\n  <text x=\"450\" y=\"456\" text-anchor=\"middle\" font-size=\"14\" fill=\"#e2e8f0\" font-weight=\"bold\">A 33% fall is not a catastrophe. It is smaller than either case study in Chapter 5.</text>\n  <text x=\"450\" y=\"482\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">Leverage does not invent a distant disaster. It converts an ordinary market event into a forced sale.</text>\n  <text x=\"450\" y=\"512\" text-anchor=\"middle\" font-size=\"13\" fill=\"#facc15\" font-weight=\"bold\">And on a short there is no equivalent line at all: the loss has no ceiling, because the price has none.</text>\n</svg>",
  "stocks-04-1-behaviour-gap": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 560\" font-family=\"Arial, Helvetica, sans-serif\" role=\"img\">\n  <rect x=\"0\" y=\"0\" width=\"900\" height=\"560\" fill=\"#0f172a\"/>\n  <text x=\"450\" y=\"34\" text-anchor=\"middle\" font-size=\"21\" fill=\"#e2e8f0\" font-weight=\"bold\">Three Answers to the Same Question, One Widely Repeated</text>\n  <text x=\"450\" y=\"57\" text-anchor=\"middle\" font-size=\"13\" fill=\"#94a3b8\">How much do fund investors lose each year to the timing of their purchases and sales?</text>\n  <text x=\"318\" y=\"124\" text-anchor=\"end\" font-size=\"13\" fill=\"#e2e8f0\">DALBAR, quoted for years</text>\n  <rect x=\"330\" y=\"98\" width=\"348.3333333333333\" height=\"42\" rx=\"3\" fill=\"#ef4444\"/>\n  <text x=\"688.3333333333333\" y=\"124\" text-anchor=\"start\" font-size=\"13\" fill=\"#f87171\" font-weight=\"bold\">about 5 to 6 points a year</text>\n  <text x=\"318\" y=\"190\" text-anchor=\"end\" font-size=\"13\" fill=\"#e2e8f0\">Morningstar Mind the Gap 2025</text>\n  <rect x=\"330\" y=\"164\" width=\"76\" height=\"42\" rx=\"3\" fill=\"#eab308\"/>\n  <text x=\"416\" y=\"190\" text-anchor=\"start\" font-size=\"13\" fill=\"#facc15\" font-weight=\"bold\">1.2 points a year</text>\n  <text x=\"318\" y=\"256\" text-anchor=\"end\" font-size=\"13\" fill=\"#e2e8f0\">Fulkerson, Jordan, Riley and Yan 2026</text>\n  <rect x=\"330\" y=\"230\" width=\"6.333333333333333\" height=\"42\" rx=\"3\" fill=\"#22c55e\"/>\n  <text x=\"346.3333333333333\" y=\"256\" text-anchor=\"start\" font-size=\"13\" fill=\"#4ade80\" font-weight=\"bold\">about 0.10 points a year</text>\n  <rect x=\"60\" y=\"296\" width=\"380\" height=\"138\" rx=\"8\" fill=\"#0f172a\" stroke=\"#ef4444\" stroke-width=\"2\"/>\n  <text x=\"250\" y=\"322\" text-anchor=\"middle\" font-size=\"14\" fill=\"#f87171\" font-weight=\"bold\">Why the top bar is wrong</text>\n  <text x=\"76\" y=\"350\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">It compares investors making ongoing</text>\n  <text x=\"76\" y=\"368\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">contributions against an index return that</text>\n  <text x=\"76\" y=\"386\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">assumes one lump sum at the start.</text>\n  <text x=\"76\" y=\"410\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">Two different questions. Shown by Pfau,</text>\n  <text x=\"76\" y=\"428\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">and independently by Kitces, in 2017.</text>\n  <rect x=\"460\" y=\"296\" width=\"380\" height=\"138\" rx=\"8\" fill=\"#0f172a\" stroke=\"#22c55e\" stroke-width=\"2\"/>\n  <text x=\"650\" y=\"322\" text-anchor=\"middle\" font-size=\"14\" fill=\"#4ade80\" font-weight=\"bold\">Why the middle bar is contested</text>\n  <text x=\"476\" y=\"350\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">Three mathematical errors identified in the</text>\n  <text x=\"476\" y=\"368\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">Financial Analysts Journal, 2026. Recomputing</text>\n  <text x=\"476\" y=\"386\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">the 2023 edition, a reported 1.7 point gap</text>\n  <text x=\"476\" y=\"404\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">should have been 0.03 points.</text>\n  <text x=\"476\" y=\"428\" text-anchor=\"start\" font-size=\"12\" fill=\"#e2e8f0\" font-weight=\"bold\">Nobody in the chain had a reason to check.</text>\n  <text x=\"450\" y=\"482\" text-anchor=\"middle\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">All three agree on the pattern: the gap is near zero in broad automatic funds and large in traded ones.</text>\n  <text x=\"450\" y=\"508\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">Barber and Odean 2000 measured the traders directly: 11.4% a year for the most active fifth, against a market at 17.9%.</text>\n  <text x=\"450\" y=\"532\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">Averaging those two populations produces a figure that describes neither of them.</text>\n</svg>",
  "stocks-04-2-fee-stack": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 560\" font-family=\"Arial, Helvetica, sans-serif\" role=\"img\">\n  <rect x=\"0\" y=\"0\" width=\"900\" height=\"560\" fill=\"#0f172a\"/>\n  <text x=\"450\" y=\"34\" text-anchor=\"middle\" font-size=\"21\" fill=\"#e2e8f0\" font-weight=\"bold\">What a Fee Takes From a Thirty-Year Contribution Schedule</text>\n  <text x=\"450\" y=\"57\" text-anchor=\"middle\" font-size=\"13\" fill=\"#94a3b8\">200 a month for 30 years, an underlying return of 7%. Total contributed: 72,000.</text>\n  <text x=\"188\" y=\"125\" text-anchor=\"end\" font-size=\"13\" fill=\"#e2e8f0\">no fee</text>\n  <rect x=\"200\" y=\"100\" width=\"357.52376\" height=\"40\" rx=\"3\" fill=\"#22c55e\"/>\n  <text x=\"567.52376\" y=\"125\" text-anchor=\"start\" font-size=\"13\" fill=\"#4ade80\" font-weight=\"bold\">235,213</text>\n  <text x=\"188\" y=\"189\" text-anchor=\"end\" font-size=\"13\" fill=\"#e2e8f0\">0.20% a year</text>\n  <rect x=\"200\" y=\"164\" width=\"344.55968\" height=\"40\" rx=\"3\" fill=\"#22c55e\"/>\n  <text x=\"554.5596800000001\" y=\"189\" text-anchor=\"start\" font-size=\"13\" fill=\"#4ade80\" font-weight=\"bold\">226,684   (fee took 3.6%)</text>\n  <text x=\"188\" y=\"253\" text-anchor=\"end\" font-size=\"13\" fill=\"#e2e8f0\">1.00% a year</text>\n  <rect x=\"200\" y=\"228\" width=\"297.69352\" height=\"40\" rx=\"3\" fill=\"#eab308\"/>\n  <text x=\"507.69352\" y=\"253\" text-anchor=\"start\" font-size=\"13\" fill=\"#facc15\" font-weight=\"bold\">195,851   (fee took 16.7%)</text>\n  <text x=\"188\" y=\"317\" text-anchor=\"end\" font-size=\"13\" fill=\"#e2e8f0\">2.00% a year</text>\n  <rect x=\"200\" y=\"292\" width=\"248.88479999999998\" height=\"40\" rx=\"3\" fill=\"#ef4444\"/>\n  <text x=\"458.8848\" y=\"317\" text-anchor=\"start\" font-size=\"13\" fill=\"#f87171\" font-weight=\"bold\">163,740   (fee took 30.4%)</text>\n  <line x1=\"60\" y1=\"368\" x2=\"840\" y2=\"368\" stroke=\"#334155\" stroke-width=\"1\"/>\n  <text x=\"450\" y=\"400\" text-anchor=\"middle\" font-size=\"14\" fill=\"#e2e8f0\" font-weight=\"bold\">A 1% fee does not take 1%. Over thirty years it takes about a sixth of everything you end up with.</text>\n  <text x=\"450\" y=\"426\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">The 2% line costs about 71,500, which is very nearly the entire 72,000 that was contributed.</text>\n  <rect x=\"150\" y=\"448\" width=\"600\" height=\"82\" rx=\"8\" fill=\"#0f172a\" stroke=\"#eab308\" stroke-width=\"2\"/>\n  <text x=\"450\" y=\"474\" text-anchor=\"middle\" font-size=\"13\" fill=\"#facc15\" font-weight=\"bold\">And charges stack</text>\n  <text x=\"450\" y=\"498\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">A fund at 0.20%, a platform at 0.35% and advice at 0.75% total 1.30% a year.</text>\n  <text x=\"450\" y=\"518\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">None looks large alone, and no statement adds them up for you.</text>\n</svg>",
  "stocks-04-3-equity-plan": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 560\" font-family=\"Arial, Helvetica, sans-serif\" role=\"img\">\n  <rect x=\"0\" y=\"0\" width=\"900\" height=\"560\" fill=\"#0f172a\"/>\n  <text x=\"450\" y=\"34\" text-anchor=\"middle\" font-size=\"21\" fill=\"#e2e8f0\" font-weight=\"bold\">Six Questions a Written Plan Answers</text>\n  <text x=\"450\" y=\"57\" text-anchor=\"middle\" font-size=\"13\" fill=\"#94a3b8\">Decisions made while calm, in writing, for use at a moment when you will not be.</text>\n  <circle cx=\"72\" cy=\"108\" r=\"18\" fill=\"#3b82f6\"/>\n  <text x=\"72\" y=\"113\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0f172a\" font-weight=\"bold\">1</text>\n  <text x=\"104\" y=\"104\" text-anchor=\"start\" font-size=\"15\" fill=\"#e2e8f0\" font-weight=\"bold\">What is this money for, and when will you need it?</text>\n  <text x=\"104\" y=\"126\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">Money needed in three years and money needed in thirty are different problems. Chapter 3 Lesson 1.</text>\n  <circle cx=\"72\" cy=\"174\" r=\"18\" fill=\"#3b82f6\"/>\n  <text x=\"72\" y=\"179\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0f172a\" font-weight=\"bold\">2</text>\n  <text x=\"104\" y=\"170\" text-anchor=\"start\" font-size=\"15\" fill=\"#e2e8f0\" font-weight=\"bold\">What will you hold?</text>\n  <text x=\"104\" y=\"192\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">Name the funds or the allocation. Not a vague intention to be diversified. Chapter 2 Lesson 5.</text>\n  <circle cx=\"72\" cy=\"240\" r=\"18\" fill=\"#22c55e\"/>\n  <text x=\"72\" y=\"245\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0f172a\" font-weight=\"bold\">3</text>\n  <text x=\"104\" y=\"236\" text-anchor=\"start\" font-size=\"15\" fill=\"#e2e8f0\" font-weight=\"bold\">How much goes in, and how often?</text>\n  <text x=\"104\" y=\"258\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">If you are averaging in, the schedule and its end date go in writing here. Chapter 3 Lesson 3.</text>\n  <circle cx=\"72\" cy=\"306\" r=\"18\" fill=\"#22c55e\"/>\n  <text x=\"72\" y=\"311\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0f172a\" font-weight=\"bold\">4</text>\n  <text x=\"104\" y=\"302\" text-anchor=\"start\" font-size=\"15\" fill=\"#e2e8f0\" font-weight=\"bold\">What is the maximum any one position may be?</text>\n  <text x=\"104\" y=\"324\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">A limit written in advance is a limit. One decided when a holding is up 300% is a negotiation.</text>\n  <circle cx=\"72\" cy=\"372\" r=\"18\" fill=\"#eab308\"/>\n  <text x=\"72\" y=\"377\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0f172a\" font-weight=\"bold\">5</text>\n  <text x=\"104\" y=\"368\" text-anchor=\"start\" font-size=\"15\" fill=\"#e2e8f0\" font-weight=\"bold\">When do you rebalance?</text>\n  <text x=\"104\" y=\"390\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">A band responds to the portfolio. A calendar date responds to the calendar. Either beats no rule.</text>\n  <circle cx=\"72\" cy=\"438\" r=\"18\" fill=\"#eab308\"/>\n  <text x=\"72\" y=\"443\" text-anchor=\"middle\" font-size=\"16\" fill=\"#0f172a\" font-weight=\"bold\">6</text>\n  <text x=\"104\" y=\"434\" text-anchor=\"start\" font-size=\"15\" fill=\"#e2e8f0\" font-weight=\"bold\">Under what conditions will you sell?</text>\n  <text x=\"104\" y=\"456\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">The money is needed; the band was breached; the fee rose; the reason for buying no longer holds.</text>\n  <line x1=\"60\" y1=\"486\" x2=\"840\" y2=\"486\" stroke=\"#334155\" stroke-width=\"1\"/>\n  <text x=\"450\" y=\"514\" text-anchor=\"middle\" font-size=\"13\" fill=\"#facc15\" font-weight=\"bold\">Not a sell condition: it fell a lot and I feel bad. That is the feeling the document exists to overrule.</text>\n  <text x=\"450\" y=\"538\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">Write it when nothing is happening. A plan drafted in a drawdown encodes the panic it was meant to prevent.</text>\n</svg>",
  "stocks-05-1-dot-com": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 560\" font-family=\"Arial, Helvetica, sans-serif\" role=\"img\">\n  <rect x=\"0\" y=\"0\" width=\"900\" height=\"560\" fill=\"#0f172a\"/>\n  <text x=\"450\" y=\"34\" text-anchor=\"middle\" font-size=\"21\" fill=\"#e2e8f0\" font-weight=\"bold\">The Nasdaq Composite, 2000 to 2015</text>\n  <text x=\"450\" y=\"57\" text-anchor=\"middle\" font-size=\"13\" fill=\"#94a3b8\">A fall of 77.9%, and a round trip of fifteen years, one month and thirteen days.</text>\n  <line x1=\"90\" y1=\"106\" x2=\"790\" y2=\"106\" stroke=\"#334155\" stroke-width=\"1\" stroke-dasharray=\"3 5\"/>\n  <text x=\"80\" y=\"110\" text-anchor=\"end\" font-size=\"12\" fill=\"#94a3b8\">5,600</text>\n  <line x1=\"90\" y1=\"173.5\" x2=\"790\" y2=\"173.5\" stroke=\"#334155\" stroke-width=\"1\" stroke-dasharray=\"3 5\"/>\n  <text x=\"80\" y=\"177.5\" text-anchor=\"end\" font-size=\"12\" fill=\"#94a3b8\">4,200</text>\n  <line x1=\"90\" y1=\"241\" x2=\"790\" y2=\"241\" stroke=\"#334155\" stroke-width=\"1\" stroke-dasharray=\"3 5\"/>\n  <text x=\"80\" y=\"245\" text-anchor=\"end\" font-size=\"12\" fill=\"#94a3b8\">2,800</text>\n  <line x1=\"90\" y1=\"308.5\" x2=\"790\" y2=\"308.5\" stroke=\"#334155\" stroke-width=\"1\" stroke-dasharray=\"3 5\"/>\n  <text x=\"80\" y=\"312.5\" text-anchor=\"end\" font-size=\"12\" fill=\"#94a3b8\">1,400</text>\n  <line x1=\"90\" y1=\"376\" x2=\"790\" y2=\"376\" stroke=\"#334155\" stroke-width=\"1\"/>\n  <text x=\"80\" y=\"380\" text-anchor=\"end\" font-size=\"12\" fill=\"#94a3b8\">0</text>\n  <text x=\"90\" y=\"398\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">Mar 2000</text>\n  <text x=\"160\" y=\"398\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\"></text>\n  <text x=\"230\" y=\"398\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">Oct 2002</text>\n  <text x=\"300\" y=\"398\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\"></text>\n  <text x=\"370\" y=\"398\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">2006</text>\n  <text x=\"440\" y=\"398\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\"></text>\n  <text x=\"510\" y=\"398\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">2009</text>\n  <text x=\"580\" y=\"398\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\"></text>\n  <text x=\"650\" y=\"398\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">2013</text>\n  <text x=\"720\" y=\"398\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\"></text>\n  <text x=\"790\" y=\"398\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">Apr 2015</text>\n  <polyline points=\"90.0,132.6 160.0,221.7 230.0,322.3 300.0,279.6 370.0,269.9 440.0,248.2 510.0,298.9 580.0,248.2 650.0,230.4 720.0,174.5 790.0,132.2\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"3\"/>\n  <text x=\"798\" y=\"136.22857142857146\" text-anchor=\"start\" font-size=\"12\" fill=\"#3b82f6\" font-weight=\"bold\"></text>\n  <circle cx=\"90\" cy=\"132.6142857142857\" r=\"6\" fill=\"#ef4444\"/>\n  <text x=\"100\" y=\"128\" text-anchor=\"start\" font-size=\"13\" fill=\"#f87171\" font-weight=\"bold\">peak 5,048.62 on 10 March 2000</text>\n  <circle cx=\"230\" cy=\"322.2892857142857\" r=\"6\" fill=\"#ef4444\"/>\n  <text x=\"240\" y=\"336\" text-anchor=\"start\" font-size=\"13\" fill=\"#f87171\" font-weight=\"bold\">trough 1,114.11 on 9 October 2002</text>\n  <circle cx=\"790\" cy=\"132.22857142857146\" r=\"6\" fill=\"#22c55e\"/>\n  <text x=\"784\" y=\"150\" text-anchor=\"end\" font-size=\"13\" fill=\"#4ade80\" font-weight=\"bold\">back above the peak, 23 April 2015</text>\n  <line x1=\"60\" y1=\"424\" x2=\"840\" y2=\"424\" stroke=\"#334155\" stroke-width=\"1\"/>\n  <text x=\"450\" y=\"454\" text-anchor=\"middle\" font-size=\"14\" fill=\"#e2e8f0\" font-weight=\"bold\">A 77.9% fall requires a gain of about 353% simply to return to where it started.</text>\n  <text x=\"450\" y=\"480\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">Someone who bought at the peak aged 55 was 70 before the position was worth what they paid, before inflation.</text>\n  <text x=\"450\" y=\"506\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">And the index recovered partly by composition: failed constituents were removed and replaced by survivors.</text>\n  <text x=\"450\" y=\"530\" text-anchor=\"middle\" font-size=\"11\" fill=\"#94a3b8\">Line shape between the marked dates is illustrative. The three dated levels are the record.</text>\n</svg>",
  "stocks-05-2-sequence-risk": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 560\" font-family=\"Arial, Helvetica, sans-serif\" role=\"img\">\n  <rect x=\"0\" y=\"0\" width=\"900\" height=\"560\" fill=\"#0f172a\"/>\n  <text x=\"450\" y=\"34\" text-anchor=\"middle\" font-size=\"21\" fill=\"#e2e8f0\" font-weight=\"bold\">The Same Market, Two Opposite Experiences</text>\n  <text x=\"450\" y=\"57\" text-anchor=\"middle\" font-size=\"13\" fill=\"#94a3b8\">The S&amp;P 500 fell 56.8% from 9 October 2007 and regained the level in about five and a half years.</text>\n  <line x1=\"90\" y1=\"100\" x2=\"790\" y2=\"100\" stroke=\"#334155\" stroke-width=\"1\" stroke-dasharray=\"3 5\"/>\n  <text x=\"80\" y=\"104\" text-anchor=\"end\" font-size=\"12\" fill=\"#94a3b8\">1,700</text>\n  <line x1=\"90\" y1=\"155\" x2=\"790\" y2=\"155\" stroke=\"#334155\" stroke-width=\"1\" stroke-dasharray=\"3 5\"/>\n  <text x=\"80\" y=\"159\" text-anchor=\"end\" font-size=\"12\" fill=\"#94a3b8\">1,275</text>\n  <line x1=\"90\" y1=\"210\" x2=\"790\" y2=\"210\" stroke=\"#334155\" stroke-width=\"1\" stroke-dasharray=\"3 5\"/>\n  <text x=\"80\" y=\"214\" text-anchor=\"end\" font-size=\"12\" fill=\"#94a3b8\">850</text>\n  <line x1=\"90\" y1=\"265\" x2=\"790\" y2=\"265\" stroke=\"#334155\" stroke-width=\"1\" stroke-dasharray=\"3 5\"/>\n  <text x=\"80\" y=\"269\" text-anchor=\"end\" font-size=\"12\" fill=\"#94a3b8\">425</text>\n  <line x1=\"90\" y1=\"320\" x2=\"790\" y2=\"320\" stroke=\"#334155\" stroke-width=\"1\"/>\n  <text x=\"80\" y=\"324\" text-anchor=\"end\" font-size=\"12\" fill=\"#94a3b8\">0</text>\n  <text x=\"90\" y=\"342\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">Oct 2007</text>\n  <text x=\"177.5\" y=\"342\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\"></text>\n  <text x=\"265\" y=\"342\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">2008</text>\n  <text x=\"352.5\" y=\"342\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">Mar 2009</text>\n  <text x=\"440\" y=\"342\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">2010</text>\n  <text x=\"527.5\" y=\"342\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">2011</text>\n  <text x=\"615\" y=\"342\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">2012</text>\n  <text x=\"702.5\" y=\"342\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\"></text>\n  <text x=\"790\" y=\"342\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">Mar 2013</text>\n  <polyline points=\"90.0,117.5 177.5,138.8 265.0,177.6 352.5,232.4 440.0,184.1 527.5,175.1 615.0,158.2 702.5,141.4 790.0,117.0\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"3\"/>\n  <text x=\"798\" y=\"120.95294117647057\" text-anchor=\"start\" font-size=\"12\" fill=\"#3b82f6\" font-weight=\"bold\"></text>\n  <circle cx=\"90\" cy=\"117.47058823529412\" r=\"6\" fill=\"#ef4444\"/>\n  <text x=\"104\" y=\"106\" text-anchor=\"start\" font-size=\"12\" fill=\"#f87171\" font-weight=\"bold\">peak 1,565.15 on 9 October 2007</text>\n  <circle cx=\"352\" cy=\"232.38823529411764\" r=\"6\" fill=\"#ef4444\"/>\n  <text x=\"362\" y=\"290\" text-anchor=\"start\" font-size=\"12\" fill=\"#f87171\" font-weight=\"bold\">trough 676.53, a fall of 56.8%, needing +131% to recover</text>\n  <rect x=\"60\" y=\"350\" width=\"380\" height=\"130\" rx=\"8\" fill=\"#0f172a\" stroke=\"#22c55e\" stroke-width=\"2\"/>\n  <text x=\"250\" y=\"376\" text-anchor=\"middle\" font-size=\"14\" fill=\"#4ade80\" font-weight=\"bold\">Contributing, aged 30</text>\n  <text x=\"76\" y=\"404\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">Every contribution from late 2008 to mid 2010</text>\n  <text x=\"76\" y=\"422\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">bought below the 2007 peak, and the March 2009</text>\n  <text x=\"76\" y=\"440\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">contributions bought near the lowest prices.</text>\n  <text x=\"76\" y=\"466\" text-anchor=\"start\" font-size=\"12\" fill=\"#e2e8f0\" font-weight=\"bold\">The fall handed them cheap assets for years.</text>\n  <rect x=\"460\" y=\"350\" width=\"380\" height=\"130\" rx=\"8\" fill=\"#0f172a\" stroke=\"#ef4444\" stroke-width=\"2\"/>\n  <text x=\"650\" y=\"376\" text-anchor=\"middle\" font-size=\"14\" fill=\"#f87171\" font-weight=\"bold\">Withdrawing 4% a year, aged 65</text>\n  <text x=\"476\" y=\"404\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">Every withdrawal between 2008 and 2011 sold</text>\n  <text x=\"476\" y=\"422\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">units at depressed prices, and those units were</text>\n  <text x=\"476\" y=\"440\" text-anchor=\"start\" font-size=\"12\" fill=\"#94a3b8\">not there to participate in the recovery.</text>\n  <text x=\"476\" y=\"466\" text-anchor=\"start\" font-size=\"12\" fill=\"#e2e8f0\" font-weight=\"bold\">The same fall permanently removed capital.</text>\n  <text x=\"450\" y=\"512\" text-anchor=\"middle\" font-size=\"13\" fill=\"#facc15\" font-weight=\"bold\">Identical portfolios, identical average returns. What differed was the direction their money was flowing.</text>\n  <text x=\"450\" y=\"538\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">Pausing contributions is not neutral either: it declines to buy at exactly the cheapest prices of the decade.</text>\n</svg>",
  "stocks-05-3-gamestop": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 560\" font-family=\"Arial, Helvetica, sans-serif\" role=\"img\">\n  <rect x=\"0\" y=\"0\" width=\"900\" height=\"560\" fill=\"#0f172a\"/>\n  <text x=\"450\" y=\"34\" text-anchor=\"middle\" font-size=\"21\" fill=\"#e2e8f0\" font-weight=\"bold\">GameStop, January 2021: The Story and the Data</text>\n  <text x=\"450\" y=\"57\" text-anchor=\"middle\" font-size=\"13\" fill=\"#94a3b8\">The explanation everyone repeats is the one the regulator examined and did not find support for.</text>\n  <rect x=\"30\" y=\"84\" width=\"265.3333333333333\" height=\"430\" rx=\"10\" fill=\"#0f172a\" stroke=\"#ef4444\" stroke-width=\"2\"/>\n  <text x=\"162.66666666666666\" y=\"114\" text-anchor=\"middle\" font-size=\"16\" fill=\"#f87171\" font-weight=\"bold\">What almost everyone says</text>\n  <text x=\"46\" y=\"146\" text-anchor=\"start\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">A short squeeze.</text>\n  <text x=\"46\" y=\"173\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">Short sellers forced to buy back,</text>\n  <text x=\"46\" y=\"192\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">their buying pushing the price</text>\n  <text x=\"46\" y=\"211\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">higher, forcing more to buy.</text>\n  <text x=\"46\" y=\"248\" text-anchor=\"start\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">Plus a gamma squeeze.</text>\n  <text x=\"46\" y=\"275\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">Dealers who sold call options buying</text>\n  <text x=\"46\" y=\"294\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">shares to hedge, buying more as the</text>\n  <text x=\"46\" y=\"313\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">price rose.</text>\n  <text x=\"46\" y=\"350\" text-anchor=\"start\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">The circumstantial case was strong.</text>\n  <text x=\"46\" y=\"377\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">More than 100% of the freely</text>\n  <text x=\"46\" y=\"396\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">tradable shares had been sold short</text>\n  <text x=\"46\" y=\"415\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">— the only meme stock where that was</text>\n  <text x=\"46\" y=\"434\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">true.</text>\n  <rect x=\"317.3333333333333\" y=\"84\" width=\"265.3333333333333\" height=\"430\" rx=\"10\" fill=\"#0f172a\" stroke=\"#22c55e\" stroke-width=\"2\"/>\n  <text x=\"450\" y=\"114\" text-anchor=\"middle\" font-size=\"16\" fill=\"#4ade80\" font-weight=\"bold\">What the SEC staff found</text>\n  <text x=\"333.3333333333333\" y=\"146\" text-anchor=\"start\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">Report published 18 October 2021.</text>\n  <text x=\"333.3333333333333\" y=\"173\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">Staff examined the order and trade</text>\n  <text x=\"333.3333333333333\" y=\"192\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">data directly.</text>\n  <text x=\"333.3333333333333\" y=\"229\" text-anchor=\"start\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">Buying came mainly from investors</text>\n  <text x=\"333.3333333333333\" y=\"248\" text-anchor=\"start\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">holding no short positions.</text>\n  <text x=\"333.3333333333333\" y=\"285\" text-anchor=\"start\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">Short covering peaked and declined</text>\n  <text x=\"333.3333333333333\" y=\"304\" text-anchor=\"start\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">before the price reached its highest</text>\n  <text x=\"333.3333333333333\" y=\"323\" text-anchor=\"start\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">levels.</text>\n  <text x=\"333.3333333333333\" y=\"360\" text-anchor=\"start\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">Neither a short nor a gamma squeeze</text>\n  <text x=\"333.3333333333333\" y=\"379\" text-anchor=\"start\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">was the primary cause.</text>\n  <text x=\"333.3333333333333\" y=\"416\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">Academic work has since disputed</text>\n  <text x=\"333.3333333333333\" y=\"435\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">parts of the report. The honest</text>\n  <text x=\"333.3333333333333\" y=\"454\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">state is a disagreement, not either</text>\n  <text x=\"333.3333333333333\" y=\"473\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">confident version.</text>\n  <rect x=\"604.6666666666666\" y=\"84\" width=\"265.3333333333333\" height=\"430\" rx=\"10\" fill=\"#0f172a\" stroke=\"#eab308\" stroke-width=\"2\"/>\n  <text x=\"737.3333333333333\" y=\"114\" text-anchor=\"middle\" font-size=\"16\" fill=\"#facc15\" font-weight=\"bold\">What actually stopped the buying</text>\n  <text x=\"620.6666666666666\" y=\"146\" text-anchor=\"start\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">28 January 2021: several brokerages</text>\n  <text x=\"620.6666666666666\" y=\"165\" text-anchor=\"start\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">allowed selling but not buying.</text>\n  <text x=\"620.6666666666666\" y=\"202\" text-anchor=\"start\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">Not an instruction. A collateral</text>\n  <text x=\"620.6666666666666\" y=\"221\" text-anchor=\"start\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">rule.</text>\n  <text x=\"620.6666666666666\" y=\"248\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">Clearing houses demand collateral</text>\n  <text x=\"620.6666666666666\" y=\"267\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">against trades awaiting settlement,</text>\n  <text x=\"620.6666666666666\" y=\"286\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">scaled to volatility and volume.</text>\n  <text x=\"620.6666666666666\" y=\"323\" text-anchor=\"start\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">Both were extreme, and the demands</text>\n  <text x=\"620.6666666666666\" y=\"342\" text-anchor=\"start\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">landed within hours.</text>\n  <text x=\"620.6666666666666\" y=\"369\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">Restricting purchases cut the</text>\n  <text x=\"620.6666666666666\" y=\"388\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">obligations needing collateral.</text>\n  <text x=\"620.6666666666666\" y=\"407\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\">Sales did not.</text>\n  <text x=\"620.6666666666666\" y=\"444\" text-anchor=\"start\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">Part of why the United States</text>\n  <text x=\"620.6666666666666\" y=\"463\" text-anchor=\"start\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">shortened settlement to one day in</text>\n  <text x=\"620.6666666666666\" y=\"482\" text-anchor=\"start\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">May 2024.</text>\n</svg>",
  "stocks-06-1-six-pillars": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 560\" font-family=\"Arial, Helvetica, sans-serif\" role=\"img\">\n  <rect x=\"0\" y=\"0\" width=\"900\" height=\"560\" fill=\"#0f172a\"/>\n  <text x=\"450\" y=\"34\" text-anchor=\"middle\" font-size=\"21\" fill=\"#e2e8f0\" font-weight=\"bold\">The Six-Pillar Thesis, Scored for an Equity</text>\n  <text x=\"450\" y=\"57\" text-anchor=\"middle\" font-size=\"13\" fill=\"#94a3b8\">A worked example. Conviction means how many independent pillars agree — independent is the hard word.</text>\n  <text x=\"168\" y=\"112\" text-anchor=\"end\" font-size=\"13\" fill=\"#e2e8f0\">Fundamentals</text>\n  <rect x=\"180\" y=\"92\" width=\"30\" height=\"30\" rx=\"3\" fill=\"#22c55e\"/>\n  <text x=\"220\" y=\"112\" text-anchor=\"start\" font-size=\"13\" fill=\"#4ade80\" font-weight=\"bold\">flat revenue, stable cash flow, no net debt — weakly supportive</text>\n  <text x=\"168\" y=\"160\" text-anchor=\"end\" font-size=\"13\" fill=\"#e2e8f0\">Valuation</text>\n  <rect x=\"180\" y=\"140\" width=\"60\" height=\"30\" rx=\"3\" fill=\"#22c55e\"/>\n  <text x=\"250\" y=\"160\" text-anchor=\"start\" font-size=\"13\" fill=\"#4ade80\" font-weight=\"bold\">9 times earnings against a ten-year average of 15 — supportive</text>\n  <text x=\"168\" y=\"208\" text-anchor=\"end\" font-size=\"13\" fill=\"#e2e8f0\">Catalyst</text>\n  <rect x=\"180\" y=\"188\" width=\"60\" height=\"30\" rx=\"3\" fill=\"#22c55e\"/>\n  <text x=\"250\" y=\"208\" text-anchor=\"start\" font-size=\"13\" fill=\"#4ade80\" font-weight=\"bold\">a contract renewal decision due within four months — supportive, with a date</text>\n  <text x=\"168\" y=\"256\" text-anchor=\"end\" font-size=\"13\" fill=\"#e2e8f0\">Positioning</text>\n  <rect x=\"180\" y=\"236\" width=\"2\" height=\"30\" rx=\"3\" fill=\"#94a3b8\"/>\n  <text x=\"192\" y=\"256\" text-anchor=\"start\" font-size=\"13\" fill=\"#94a3b8\" font-weight=\"bold\">short interest low, no unusual flows — neutral</text>\n  <text x=\"168\" y=\"304\" text-anchor=\"end\" font-size=\"13\" fill=\"#e2e8f0\">Momentum</text>\n  <rect x=\"180\" y=\"284\" width=\"60\" height=\"30\" rx=\"3\" fill=\"#ef4444\"/>\n  <text x=\"250\" y=\"304\" text-anchor=\"start\" font-size=\"13\" fill=\"#f87171\" font-weight=\"bold\">the shares have fallen 30% over twelve months — against</text>\n  <text x=\"168\" y=\"352\" text-anchor=\"end\" font-size=\"13\" fill=\"#e2e8f0\">Carry</text>\n  <rect x=\"180\" y=\"332\" width=\"60\" height=\"30\" rx=\"3\" fill=\"#22c55e\"/>\n  <text x=\"250\" y=\"352\" text-anchor=\"start\" font-size=\"13\" fill=\"#4ade80\" font-weight=\"bold\">a 4% dividend covered twice by earnings — supportive</text>\n  <line x1=\"60\" y1=\"388\" x2=\"840\" y2=\"388\" stroke=\"#334155\" stroke-width=\"1\"/>\n  <text x=\"450\" y=\"416\" text-anchor=\"middle\" font-size=\"14\" fill=\"#e2e8f0\" font-weight=\"bold\">Four supportive, one neutral, one against, and a dated catalyst. That is a genuine thesis.</text>\n  <rect x=\"120\" y=\"434\" width=\"660\" height=\"100\" rx=\"8\" fill=\"#0f172a\" stroke=\"#eab308\" stroke-width=\"2\"/>\n  <text x=\"450\" y=\"460\" text-anchor=\"middle\" font-size=\"13\" fill=\"#facc15\" font-weight=\"bold\">Momentum disagreeing is the normal case, not a contradiction</text>\n  <text x=\"450\" y=\"484\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">Asness, Moskowitz and Pedersen 2013 found value and momentum negatively correlated within and across</text>\n  <text x=\"450\" y=\"502\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">asset classes. A cheap share is usually cheap because it has been falling.</text>\n  <text x=\"450\" y=\"524\" text-anchor=\"middle\" font-size=\"12\" fill=\"#e2e8f0\" font-weight=\"bold\">The common error: counting one falling price as valuation, carry and sentiment. One fact, three vocabularies.</text>\n</svg>",
  "stocks-06-2-transmission-chain": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 560\" font-family=\"Arial, Helvetica, sans-serif\" role=\"img\">\n  <rect x=\"0\" y=\"0\" width=\"900\" height=\"560\" fill=\"#0f172a\"/>\n  <text x=\"450\" y=\"34\" text-anchor=\"middle\" font-size=\"21\" fill=\"#e2e8f0\" font-weight=\"bold\">Equities Sit Late on the Transmission Chain</text>\n  <text x=\"450\" y=\"57\" text-anchor=\"middle\" font-size=\"13\" fill=\"#94a3b8\">By the time a policy change is visible in share prices, it has already appeared twice.</text>\n  <rect x=\"40\" y=\"108\" width=\"127.2\" height=\"88\" rx=\"8\" fill=\"#0f172a\" stroke=\"#eab308\" stroke-width=\"2\"/>\n  <text x=\"103.6\" y=\"136\" text-anchor=\"middle\" font-size=\"13\" fill=\"#eab308\" font-weight=\"bold\">Interest rates</text>\n  <text x=\"103.6\" y=\"218\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">the policy change</text>\n  <text x=\"103.6\" y=\"233\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">itself</text>\n  <text x=\"190.2\" y=\"157\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">then</text>\n  <rect x=\"213.2\" y=\"108\" width=\"127.2\" height=\"88\" rx=\"8\" fill=\"#0f172a\" stroke=\"#eab308\" stroke-width=\"2\"/>\n  <text x=\"276.8\" y=\"136\" text-anchor=\"middle\" font-size=\"13\" fill=\"#eab308\" font-weight=\"bold\">Currencies and</text>\n  <text x=\"276.8\" y=\"152\" text-anchor=\"middle\" font-size=\"13\" fill=\"#eab308\" font-weight=\"bold\">bonds</text>\n  <text x=\"276.8\" y=\"218\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">yields move, then FX</text>\n  <text x=\"276.8\" y=\"233\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">adjusts</text>\n  <text x=\"363.4\" y=\"157\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">then</text>\n  <rect x=\"386.4\" y=\"108\" width=\"127.2\" height=\"88\" rx=\"8\" fill=\"#0f172a\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n  <text x=\"450\" y=\"136\" text-anchor=\"middle\" font-size=\"13\" fill=\"#3b82f6\" font-weight=\"bold\">Credit</text>\n  <text x=\"450\" y=\"218\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">spreads widen as</text>\n  <text x=\"450\" y=\"233\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">borrowing costs rise</text>\n  <text x=\"536.6\" y=\"157\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">then</text>\n  <rect x=\"559.5999999999999\" y=\"108\" width=\"127.2\" height=\"88\" rx=\"8\" fill=\"#0f172a\" stroke=\"#ef4444\" stroke-width=\"2\"/>\n  <text x=\"623.1999999999999\" y=\"136\" text-anchor=\"middle\" font-size=\"13\" fill=\"#ef4444\" font-weight=\"bold\">Equities</text>\n  <text x=\"623.1999999999999\" y=\"218\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">two channels at once</text>\n  <text x=\"709.8\" y=\"157\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">then</text>\n  <rect x=\"732.8\" y=\"108\" width=\"127.2\" height=\"88\" rx=\"8\" fill=\"#0f172a\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n  <text x=\"796.4\" y=\"136\" text-anchor=\"middle\" font-size=\"13\" fill=\"#94a3b8\" font-weight=\"bold\">Commodities and</text>\n  <text x=\"796.4\" y=\"152\" text-anchor=\"middle\" font-size=\"13\" fill=\"#94a3b8\" font-weight=\"bold\">crypto</text>\n  <text x=\"796.4\" y=\"218\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">furthest along the</text>\n  <text x=\"796.4\" y=\"233\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">chain</text>\n  <rect x=\"120\" y=\"268\" width=\"660\" height=\"96\" rx=\"8\" fill=\"#0f172a\" stroke=\"#ef4444\" stroke-width=\"2\"/>\n  <text x=\"450\" y=\"294\" text-anchor=\"middle\" font-size=\"14\" fill=\"#f87171\" font-weight=\"bold\">Why rates hit equities twice</text>\n  <text x=\"450\" y=\"320\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">A higher discount rate reduces the present value of future cash flows, and reduces distant ones most.</text>\n  <text x=\"450\" y=\"340\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">Higher rates also slow the economy those cash flows come from.</text>\n  <text x=\"450\" y=\"394\" text-anchor=\"middle\" font-size=\"14\" fill=\"#e2e8f0\" font-weight=\"bold\">A high multiple is a bet on distant profits, which is exactly the bet a rate rise damages.</text>\n  <line x1=\"60\" y1=\"416\" x2=\"840\" y2=\"416\" stroke=\"#334155\" stroke-width=\"1\"/>\n  <text x=\"450\" y=\"446\" text-anchor=\"middle\" font-size=\"13\" fill=\"#facc15\" font-weight=\"bold\">Someone watching only equities is reading the last link and calling it news.</text>\n  <text x=\"450\" y=\"472\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">This is not market timing. Regime mapping tells you which pillar to trust in the environment you are already in.</text>\n  <text x=\"450\" y=\"498\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">Regimes shift gradually upward and abruptly downward, so a plan built on reacting meets the slower one.</text>\n  <text x=\"450\" y=\"524\" text-anchor=\"middle\" font-size=\"12\" fill=\"#e2e8f0\" font-weight=\"bold\">And when nothing aligns, the correct discretionary position is none.</text>\n</svg>",
  "stocks-06-3-correlation-tail": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 560\" font-family=\"Arial, Helvetica, sans-serif\" role=\"img\">\n  <rect x=\"0\" y=\"0\" width=\"900\" height=\"560\" fill=\"#0f172a\"/>\n  <text x=\"450\" y=\"34\" text-anchor=\"middle\" font-size=\"21\" fill=\"#e2e8f0\" font-weight=\"bold\">Diversification Is Weakest Exactly When You Need It</text>\n  <text x=\"450\" y=\"57\" text-anchor=\"middle\" font-size=\"13\" fill=\"#94a3b8\">Longin and Solnik 2001 modelled the tails of international equity returns using extreme value theory.</text>\n  <text x=\"240\" y=\"100\" text-anchor=\"middle\" font-size=\"15\" fill=\"#4ade80\" font-weight=\"bold\">Ordinary and rising months</text>\n  <rect x=\"80\" y=\"118\" width=\"320\" height=\"200\" rx=\"10\" fill=\"#0f172a\" stroke=\"#22c55e\" stroke-width=\"2\"/>\n  <circle cx=\"130\" cy=\"200\" r=\"20\" fill=\"#22c55e\" fill-opacity=\"0.6\"/>\n  <circle cx=\"190\" cy=\"250\" r=\"20\" fill=\"#22c55e\" fill-opacity=\"0.6\"/>\n  <circle cx=\"250\" cy=\"200\" r=\"20\" fill=\"#22c55e\" fill-opacity=\"0.6\"/>\n  <circle cx=\"310\" cy=\"250\" r=\"20\" fill=\"#22c55e\" fill-opacity=\"0.6\"/>\n  <circle cx=\"370\" cy=\"200\" r=\"20\" fill=\"#22c55e\" fill-opacity=\"0.6\"/>\n  <text x=\"240\" y=\"292\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">five markets, moving somewhat separately</text>\n  <text x=\"660\" y=\"100\" text-anchor=\"middle\" font-size=\"15\" fill=\"#f87171\" font-weight=\"bold\">The worst months</text>\n  <rect x=\"500\" y=\"118\" width=\"320\" height=\"200\" rx=\"10\" fill=\"#0f172a\" stroke=\"#ef4444\" stroke-width=\"2\"/>\n  <circle cx=\"640\" cy=\"210\" r=\"20\" fill=\"#ef4444\" fill-opacity=\"0.5\"/>\n  <circle cx=\"650\" cy=\"210\" r=\"20\" fill=\"#ef4444\" fill-opacity=\"0.5\"/>\n  <circle cx=\"660\" cy=\"210\" r=\"20\" fill=\"#ef4444\" fill-opacity=\"0.5\"/>\n  <circle cx=\"670\" cy=\"210\" r=\"20\" fill=\"#ef4444\" fill-opacity=\"0.5\"/>\n  <circle cx=\"680\" cy=\"210\" r=\"20\" fill=\"#ef4444\" fill-opacity=\"0.5\"/>\n  <text x=\"660\" y=\"292\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">the same five markets, moving as one</text>\n  <rect x=\"120\" y=\"336\" width=\"660\" height=\"96\" rx=\"8\" fill=\"#0f172a\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n  <text x=\"450\" y=\"362\" text-anchor=\"middle\" font-size=\"14\" fill=\"#60a5fa\" font-weight=\"bold\">The finding is asymmetric</text>\n  <text x=\"450\" y=\"388\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">Correlation rises in the negative tail, when markets fall together. It does not rise in the positive tail.</text>\n  <text x=\"450\" y=\"408\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">They rejected multivariate normality for the negative tail and not for the positive one.</text>\n  <text x=\"450\" y=\"464\" text-anchor=\"middle\" font-size=\"13\" fill=\"#e2e8f0\" font-weight=\"bold\">A portfolio spread across countries behaves like several investments for years, and like one on the worst days.</text>\n  <text x=\"450\" y=\"490\" text-anchor=\"middle\" font-size=\"12\" fill=\"#94a3b8\">Not an argument against diversifying. An argument against expecting it to deliver in the drawdown what it delivers on average.</text>\n  <text x=\"450\" y=\"516\" text-anchor=\"middle\" font-size=\"12\" fill=\"#facc15\" font-weight=\"bold\">The number to ask for is the correlation during the worst 5% of months. It is almost never the one in the advertisement.</text>\n</svg>",
};
